INSERT INTO `wp_options` VALUES (1008,'xts-theme_settings_default-css-data','@font-face {\n	font-weight: normal;\n	font-style: normal;\n	font-family: \"woodmart-font\";\n	src: url(\"//localhost:10003/wp-content/themes/woodmart/fonts/woodmart-font-2-400.woff2?v=8.4.1\") format(\"woff2\");\n}\n\n@font-face {\n	font-family: \"star\";\n	font-weight: 400;\n	font-style: normal;\n	src: url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/star.eot?#iefix\") format(\"embedded-opentype\"), url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/star.woff\") format(\"woff\"), url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/star.ttf\") format(\"truetype\"), url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/star.svg#star\") format(\"svg\");\n}\n\n@font-face {\n	font-family: \"WooCommerce\";\n	font-weight: 400;\n	font-style: normal;\n	src: url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.eot?#iefix\") format(\"embedded-opentype\"), url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.woff\") format(\"woff\"), url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.ttf\") format(\"truetype\"), url(\"//localhost:10003/wp-content/plugins/woocommerce/assets/fonts/WooCommerce.svg#WooCommerce\") format(\"svg\");\n}\n\n:root {\n	--wd-text-font: \"Open Sans\", Arial, Helvetica, sans-serif;\n	--wd-text-font-weight: 400;\n	--wd-text-color: #767676;\n	--wd-text-font-size: 15px;\n	--wd-title-font: \"Lexend Deca\", Arial, Helvetica, sans-serif;\n	--wd-title-font-weight: 500;\n	--wd-title-color: #242424;\n	--wd-entities-title-font: \"Lexend Deca\", Arial, Helvetica, sans-serif;\n	--wd-entities-title-font-weight: 500;\n	--wd-entities-title-color: #333333;\n	--wd-entities-title-color-hover: rgb(51 51 51 / 65%);\n	--wd-alternative-font: \"Lexend Deca\", Arial, Helvetica, sans-serif;\n	--wd-widget-title-font: \"Lexend Deca\", Arial, Helvetica, sans-serif;\n	--wd-widget-title-font-weight: 500;\n	--wd-widget-title-transform: capitalize;\n	--wd-widget-title-color: #333;\n	--wd-widget-title-font-size: 16px;\n	--wd-header-el-font: \"Open Sans\", Arial, Helvetica, sans-serif;\n	--wd-header-el-font-weight: 600;\n	--wd-header-el-transform: capitalize;\n	--wd-header-el-font-size: 13px;\n	--wd-brd-radius: 10px;\n	--wd-otl-style: dotted;\n	--wd-otl-width: 2px;\n	--wd-primary-color: rgb(28,97,231);\n	--wd-alternative-color: rgba(28,97,231,0.2);\n	--btn-default-bgcolor: rgb(225,235,255);\n	--btn-default-bgcolor-hover: rgb(219,227,249);\n	--btn-default-color: rgb(28,97,231);\n	--btn-default-color-hover: rgb(28,97,231);\n	--btn-accented-bgcolor: rgb(28,97,231);\n	--btn-accented-bgcolor-hover: rgb(28,97,231);\n	--btn-transform: capitalize;\n	--wd-form-brd-width: 1px;\n	--notices-success-bg: #459647;\n	--notices-success-color: #fff;\n	--notices-warning-bg: #E0B252;\n	--notices-warning-color: #fff;\n	--wd-link-color: #333333;\n	--wd-link-color-hover: #242424;\n}\n.wd-age-verify-wrap {\n	--wd-popup-width: 500px;\n}\n.wd-popup.wd-promo-popup {\n	background-color: #111111;\n	background-image: none;\n	background-repeat: no-repeat;\n	background-size: contain;\n	background-position: left center;\n}\n.wd-promo-popup-wrap {\n	--wd-popup-width: 800px;\n}\n:is(.woodmart-archive-shop .wd-builder-off,.wd-wishlist-content,.related-and-upsells,.cart-collaterals,.wd-shop-product,.wd-fbt) .wd-products-with-bg, :is(.woodmart-archive-shop .wd-builder-off,.wd-wishlist-content,.related-and-upsells,.cart-collaterals,.wd-shop-product,.wd-fbt) .wd-products-with-bg :is(.wd-product,.wd-cat) {\n	--wd-prod-bg:rgb(255,255,255);\n	--wd-bordered-bg:rgb(255,255,255);\n}\n:is(.woodmart-woocommerce-layered-nav, .wd-product-category-filter) .wd-scroll-content {\n	max-height: 223px;\n}\n.wd-page-title .wd-page-title-bg img {\n	object-fit: cover;\n	object-position: center center;\n}\n.wd-footer {\n	background-color: #ffffff;\n	background-image: none;\n}\nhtml .wd-nav