INSERT INTO `wp_options` VALUES (4217,'_site_transient_feed_d117b5738fbd35bd8c0391cda1f2b5d9','a:6:{s:5:\"child\";a:1:{s:0:\"\";a:1:{s:3:\"rss\";a:1:{i:0;a:6:{s:4:\"data\";s:3:\"\n\n\n\";s:7:\"attribs\";a:1:{s:0:\"\";a:1:{s:7:\"version\";s:3:\"2.0\";}}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:1:{s:7:\"channel\";a:1:{i:0;a:6:{s:4:\"data\";s:112:\"\n	\n	\n	\n	\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:1:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:16:\"WordPress Planet\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:28:\"http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:8:\"language\";a:1:{i:0;a:5:{s:4:\"data\";s:2:\"en\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"WordPress Planet - http://planet.wordpress.org/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"item\";a:50:{i:0;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:50:\"WordPress.org blog: WordPress 6.9.3 and 7.0 beta 4\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=20166\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:66:\"https://wordpress.org/news/2026/03/wordpress-6-9-3-and-7-0-beta-4/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5836:\"<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/news/2026/03/wordpress-6-9-2-release/\">WordPress 6.9.2 was released earlier today</a> and addressed 10 security issues.</p>\n\n\n\n<p class=\"wp-block-paragraph\">A few users have subsequently reported an issue where the front end of their site was appearing blank after updating to 6.9.2. The issue has been narrowed down to some themes using an unusual approach to loading template files via &#8220;stringable objects&#8221; instead of primitive strings for file paths.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Although this is is not an officially supported approach to loading template files in WordPress (the <code>template_include</code> filter only accepts a string), it nevertheless caused some sites to break. As a result, the Security Team has decided to address this in a fast follow 6.9.3 release.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As always,<strong> it is recommended that you update your sites to the latest version of WordPress immediately.</strong> This ensures your site is protected by all available security fixes in 6.9.2 and that you will not be affected by the bug fixed in 6.9.3.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Many thanks to those who reported the issue, assisted in narrowing down the problem, and helped with the fix.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/wordpress-6.9.3.zip\">download WordPress 6.9.3 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin shortly. You don&#8217;t have to do a thing!</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information on WordPress 6.9.3, please visit the <a href=\"https://wordpress.org/documentation/wordpress-version/version-6-9-3/\">version page on the HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">WordPress 7.0 beta 4</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The next major release of WordPress will be <a href=\"https://make.wordpress.org/core/7-0/\">version 7.0</a>, which is planned for April 9, 2026. The Security Team has decided to package a new beta release (7.0 beta 4) to keep everyone protected from the patched vulnerabilities, including the dedicated members of the community focusing their time and effort on testing the upcoming release.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This will be an additional beta release in the 7.0 release cycle.</strong> The schedule will remain the same going forward, but with five total beta releases instead of the previously planned four. The next 7.0 beta release is still scheduled for Thursday, March 12th.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta version of the WordPress software is still under development</strong>. Please do not install, run, or test WordPress 7.0 beta versions on production or mission-critical websites. Instead, you should evaluate Beta 4 on a test server and site.</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream.)</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.0-beta4.zip\">Beta 4 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a> command: <br /><code>wp core update --version=7.0-beta</code>4</td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use the <a href=\"https://playground.wordpress.net/?php=8.0&amp;wp=beta&amp;networking=no&amp;language=&amp;multisite=no&amp;random=y4q1rn88xn\">WordPress Playground instance</a> to test the software directly in your browser.  No setup is required – just click and go! </td></tr></tbody></table></figure>\n\n\n\n<h2 class=\"wp-block-heading\">Beta 4 updates and highlights</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 Beta 4 contains the ten security patches shipped in WordPress 6.9.2, and more than 49 updates and fixes since the Beta 3 release, including 14 in the Editor and 35 in Core. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Each beta cycle focuses on bug fixes. More are on the way, thanks to your help with testing. You can browse the technical details for all issues addressed since Beta 3 at these links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/compare/f4d8a5803aa2fbe26e7d9af4d17e80a622b7bab8...9b8144036fa5faf75de43d4502ff9809fcf689ad\">GitHub commits for 7.0 </a> since March 5, 2026</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=03%2F05%2F2026..03%2F10%2F2026&amp;milestone=7.0&amp;group=component&amp;col=id&amp;col=summary&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Closed Trac tickets for 7.0</a> since March 5, 2026</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">As always, a successful release depends on your confirmation during testing. So please download and test!</p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props <a class=\"mention\" href=\"https://profiles.wordpress.org/peterwilson/\"><span class=\"mentions-prefix\">@</span>peterwilson</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/desrosj/\"><span class=\"mentions-prefix\">@</span>desrosj</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/marybaum/\"><span class=\"mentions-prefix\">@</span>marybaum</a>, <a class=\"mention\" href=\"https://profiles.wordpress.org/amykamala/\"><span class=\"mentions-prefix\">@</span>amykamala</a> for peer reviewing.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Mar 2026 23:41:33 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:1;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:43:\"WordPress.org blog: WordPress 6.9.2 Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=20142\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:59:\"https://wordpress.org/news/2026/03/wordpress-6-9-2-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4649:\"<h2 class=\"wp-block-heading\">WordPress 6.9.2 is now available!</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This is a security release that features several fixes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because this is a security release,<strong> it is recommended that you update your sites immediately</strong>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You can <a href=\"https://wordpress.org/wordpress-6.9.2.zip\">download WordPress 6.9.2 from WordPress.org</a>, or visit your WordPress Dashboard, click “Updates”, and then click “Update Now”. If you have sites that support automatic background updates, the update process will begin automatically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The next major release will be <a href=\"https://make.wordpress.org/core/7-0/\">version 7.0</a>, which is planned for April 9th, 2026.</p>\n\n\n\n<p class=\"wp-block-paragraph\">For more information on WordPress 6.9.2, please visit the <a href=\"https://wordpress.org/documentation/wordpress-version/version-6-9-2/\">version page on the HelpHub site</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Security updates included in this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">The security team would like to thank the following people for <a href=\"https://hackerone.com/wordpress?type=team\">responsibly reporting vulnerabilities</a>, and allowing them to be fixed in this release:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li>A Blind SSRF issue reported by <a href=\"https://hackerone.com/sibwtf\">sibwtf</a>, and subsequently by several other researchers while the fix was being worked on</li>\n\n\n\n<li>A PoP-chain weakness in the HTML API and Block Registry reported by <a href=\"https://github.com/hackerlo2003\">Phat RiO</a></li>\n\n\n\n<li>A regex DoS weakness in numeric character references reported by Dennis Snell of the WordPress Security Team</li>\n\n\n\n<li>A stored XSS in nav menus reported by <a href=\"https://x.com/Savphill\">Phill Savage</a></li>\n\n\n\n<li>An AJAX <code>query-attachments</code> authorization bypass reported by <a href=\"https://www.vitalysim.com/\">Vitaly Simonovich</a></li>\n\n\n\n<li>A stored XSS via the <code>data-wp-bind</code> directive reported by <a href=\"https://profiles.wordpress.org/kaminuma/\">kaminuma</a></li>\n\n\n\n<li>An XSS that allows overridding client-side templates in the admin area reported by <a href=\"https://hackerone.com/amosec\">Asaf Mozes</a></li>\n\n\n\n<li>A PclZip path traversal issue reported independently by <a href=\"https://profiles.wordpress.org/francescocarlucci/\">Francesco Carlucci</a> and <a href=\"https://profiles.wordpress.org/kaminuma/\">kaminuma</a></li>\n\n\n\n<li>An authorization bypass on the Notes feature reported by <a href=\"https://profiles.wordpress.org/kaminuma/\">kaminuma</a></li>\n\n\n\n<li>An XXE in the external getID3 library reported by <a href=\"https://profiles.wordpress.org/regex33/\">Youssef Achtatal</a></li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">The WordPress security team have worked with the maintainer of the external getID3 library, James Heinrich, to coordinate a fix to getID3. A new version of getID3 <a href=\"https://github.com/JamesHeinrich/getID3/releases\">is available here</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">As a courtesy, these fixes are being backported, where necessary, to all branches eligible to receive security fixes (currently through 4.7). As a reminder, <strong>only the most recent version of WordPress is actively supported</strong>. The backports are in progress and will ship as they become ready.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Thank you to these WordPress contributors</h2>\n\n\n\n<p class=\"wp-block-paragraph\">This release was led by <a href=\"https://profiles.wordpress.org/johnbillion/\">John Blackbourn</a>. In addition to the security researchers mentioned above, WordPress 6.9.2 would not have been possible without the contributions of the following people: <a href=\"https://profiles.wordpress.org/dmsnell/\">Dennis Snell</a>, <a href=\"https://profiles.wordpress.org/xknown/\">Alex Concha</a>, <a href=\"https://profiles.wordpress.org/jonsurrell/\">Jon Surrell</a>, <a href=\"https://profiles.wordpress.org/isabel_brison/\">Isabel Brison</a>, <a href=\"https://profiles.wordpress.org/peterwilsoncc/\">Peter Wilson</a>, <a href=\"https://profiles.wordpress.org/desrosj/\">Jonathan Desrosiers</a>, <a href=\"https://profiles.wordpress.org/audrasjb/\">Jb Audras</a>, <a href=\"https://profiles.wordpress.org/luisherranz/\">Luis Herranz</a>, <a href=\"https://profiles.wordpress.org/jorbin/\">Aaron Jorbin</a>, <a href=\"https://profiles.wordpress.org/westonruter/\">Weston Ruter</a>, and <a href=\"https://profiles.wordpress.org/ocean90/\">Dominik Schilling</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Mar 2026 15:43:19 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:15:\"John Blackbourn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:2;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:114:\"Open Channels FM: Behind the Scenes at CloudFest Europe’s Playground for Cloud, Security, and Hosting Innovation\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=2550972\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:116:\"https://openchannels.fm/behind-the-scenes-at-cloudfest-europes-playground-for-cloud-security-and-hosting-innovation/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:183:\"In this episode Soeren, Myles and Robert discuss CloudFest 2026, highlighting its unique amusement park setting, various networking opportunities, and some new features for attendees.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Tue, 10 Mar 2026 09:10:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:3;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:30:\"Matt: Gone (Almost) Phishin’\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=151341\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:42:\"https://ma.tt/2026/03/gone-almost-phishin/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:4817:\"<p class=\"wp-block-paragraph\">This is a little embarrassing to share, but I&#8217;d rather someone else be able to spot a dangerous scam before they fall for it. So, here goes.</p>\n\n\n\n<p class=\"wp-block-paragraph\">One evening last month, my Apple Watch, iPhone, and Mac all lit up with a message prompting me to reset my password<em>.</em> This came out of nowhere; I hadn&#8217;t done anything to elicit it. I even had <a href=\"https://support.apple.com/en-us/105120\">Lockdown Mode</a> running on all my devices. It didn’t matter. Someone was spamming Apple&#8217;s legitimate password reset flow against my account—a technique<a href=\"https://krebsonsecurity.com/2024/03/recent-mfa-bombing-attacks-targeting-apple-users/\"> Krebs documented back in 2024</a>. I dismissed the prompts, but the stage was set.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What made the attack impressive was the next move: The scammers actually contacted Apple Support themselves, pretending to be me, and opened a real case claiming I&#8217;d lost my phone and needed to update my number. That generated a real case ID, and triggered real Apple emails to my inbox,<em> properly signed</em>, from Apple&#8217;s actual servers. These were legitimate; no filter on earth could have caught them.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-151420\" height=\"587\" src=\"https://i0.wp.com/ma.tt/files/2026/03/CleanShot-2026-02-07-at-19.36.31%402x-1-1024x996.png?resize=604%2C587&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Then &#8220;Alexander from Apple Support&#8221; called. He was calm, knowledgeable, and <em>careful</em>. His first moves were solid security advice: check your account, verify nothing&#8217;s changed, consider updating your password. He was so good that I actually thanked him for being excellent at his job.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That, of course, was when he moved into the next phase of the attack.</p>\n\n\n\n<p class=\"wp-block-paragraph\">He texted me a link to review and cancel the &#8220;pending request.&#8221; The site, audit-apple.com, was a pixel-perfect Apple replica, and displayed the exact case ID from the real emails I&#8217;d just received. There was even a fake chat transcript of the scammers&#8217; actual conversation with Apple, presented back to me as evidence of the attack against my account. At the bottom of the page was a Sign in with Apple button that he told me to use.</p>\n\n\n\n<figure class=\"wp-block-gallery has-nested-images columns-default is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex\">\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-151411\" height=\"395\" src=\"https://i0.wp.com/ma.tt/files/2026/03/CleanShot-2026-02-07-at-18.14.37%402x-1024x670.png?resize=604%2C395&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n\n\n\n<figure class=\"wp-block-image size-large\"><img alt=\"\" class=\"wp-image-151412\" height=\"418\" src=\"https://i0.wp.com/ma.tt/files/2026/03/CleanShot-2026-02-07-at-18.08.36%402x-1024x708.png?resize=604%2C418&#038;quality=80&#038;ssl=1\" width=\"604\" /></figure>\n</figure>\n\n\n\n<p class=\"wp-block-paragraph\">I started poking at the page and noticed I could enter any case ID and get the same result. Nothing was being validated. It was all theater.</p>\n\n\n\n<p class=\"wp-block-paragraph\">&#8220;This is really good,&#8221; I told Alexander. &#8220;This is obviously phishing. So tell me about the scam.&#8221;</p>\n\n\n\n<p class=\"wp-block-paragraph\">Silence. *Click*.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Once I’d suspected what was happening, I’d started recording the call, so I was able to save a good chunk of it, which Jamie Marsland used to make a video about the encounter. You can hear for yourself exactly how convincing “Alexander” was.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So let my almost-disaster help you avoid your own. Remember these rules.</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><strong>Don’t approve any password-reset prompts</strong>—those are the first part of the attack. Do not pass Go, just head directly to your Apple ID settings. </li>\n\n\n\n<li><strong>Apple will </strong><strong><em>never</em></strong><strong> call you first.</strong> </li>\n\n\n\n<li>When you get an email from Apple—or, really, anyone telling you to complete a digital security measure—<strong>check the URL</strong> they’re trying to send you to. Apple Support lives on apple.com and getsupport.apple.com, nowhere else.</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">After all, the best protection is knowing what this looks like before it happens.</p>\n\n\n\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Mon, 09 Mar 2026 15:11:29 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:4;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:101:\"Gutenberg Times: PHP-only blocks, WordCamp Asia, Dev Notes for WordPress 7.0 — Weekend Edition #360\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://gutenbergtimes.com/?p=44585\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:105:\"https://gutenbergtimes.com/php-only-blocks-wordcamp-asia-dev-notes-for-wordpress-7-0-weekend-edition-360/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:24117:\"<p class=\"wp-block-paragraph\">Hi there,</p>\n\n\n\n<p class=\"wp-block-paragraph\">I held my first walk-through of WordPress 7.0 with friends at the Santa Clarita WordPress Meetup. The group was really excited about all the big new features and the small quality-of-life (QoL) improvements.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jessica Lyschik and I also discussed many features coming to WordPress 7.0 on our latest podcast episode. Listen in if you are curious. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Below you also find the links to the first set of Dev Notes for WordPress 7.0. Beta 4 will come out next week (3/12). Release candidate 1 is scheduled for March 19. It is now time to <a href=\"https://make.wordpress.org/test/2026/02/20/help-test-wordpress-7-0/\">help test WordPress 7.0</a></p>\n\n\n\n<p class=\"wp-block-paragraph\">Enjoy your weekend and these notes. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Yours, <img alt=\"💕\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f495.png\" style=\"height: 1em;\" /><br /><em>Birgit</em></p>\n\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n\n\n<p class=\"wp-block-paragraph\">WordCamp Asia heads to Mumbai on April 10–11, and I shared <a href=\"https://gutenbergtimes.com/schedule-of-wordcamp-asia-birgits-selected-sessions/\"><strong>my personally curated session picks</strong></a> — leaning heavily into block editor, themes, and AI. Highlights include Ryan Welcher on the Interactivity API, a Playground + AI testing pipelines talk by Fellyph Cintra, and a closing keynote from Matt Mullenweg. I will also be leading a Contributor Day workshop on building a block theme from scratch. <a href=\"https://asia.wordcamp.org/2026/schedule/\">The schedule</a> still has several TBD slots, so it&#8217;s worth checking back. </p>\n\n\n\n<figure class=\"wp-block-image size-large\"><a href=\"https://asia.wordcamp.org/2026/schedule/\"><img alt=\"Networking at WordCamp Asia\" class=\"wp-image-44578\" height=\"364\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/03/WordCamp-Asia-Schedule-2026.jpg?resize=652%2C364&#038;ssl=1\" width=\"652\" /></a></figure>\n\n\n\n<p class=\"wp-block-paragraph\"><em><a href=\"https://asia.wordcamp.org/2026/event-pass/?refresh=true#get-your-pass\">Get your WordCamp Asia 2026 event pass</a> and join the WordPress community in Mumbai on April 9–11!</em></p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"0-word-press-release-information\">Developing Gutenberg and WordPress</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/news/2026/03/wordpress-7-0-beta-3/\"><strong>WordPress 7.0 Beta 3 </strong></a>is now available for testing. The final release is coming closer. It&#8217;s the time of the release cycle when <strong>Developer Notes</strong> are published ahead of Release Candidate 1.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">For the <strong><a href=\"https://make.wordpress.org/core/2026/03/04/breadcrumb-block-filters/\">new Breadcrumbs block</a></strong>, <strong>Nik Tsekouras</strong> documents the two PHP filters developers will want to know. <code>block_core_breadcrumbs_items</code> lets you modify, add, or remove items just before rendering — handy for prepending a custom &#8220;Shop&#8221; crumb in WooCommerce. <code>block_core_breadcrumbs_post_type_settings</code> gives you control over which taxonomy and term appear in the trail, with sensible fallback behavior when your preferred term isn&#8217;t assigned. Props to Karol Manijak for the implementation.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Dave Smith</strong> details one of the more exciting 7.0 additions for theme developers: <strong><a href=\"https://make.wordpress.org/core/2026/03/04/customisable-navigation-overlays-in-wordpress-7-0/\">Customisable Navigation Overlays</a>.</strong> Mobile hamburger menus were previously locked to a fixed default design — now you can build your overlay from any blocks and patterns directly in the Site Editor. Themes can bundle overlays as template parts registered with a new <code>navigation-overlay</code> area in <code>theme.json</code>. The feature is opt-in currently full-screen only, and props go to <strong>Mike McAlister</strong>, whose <a href=\"https://wordpress.org/plugins/ollie-menu-designer/\">Ollie Menu Designer plugin</a> helped validate the community demand.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Luis Herranz</strong> outlines key updates in the <a href=\"https://make.wordpress.org/core/2026/03/04/changes-to-the-interactivity-api-in-wordpress-7-0/\"><strong>Interactivity API changes in WordPress 7.0</strong></a>. The main highlight is the new <code>watch()</code> function, which helps developers to track state changes outside the DOM for tasks like logging and analytics. Additionally, <code>state.url</code> in <code>core/router</code> will now be filled by the server, improving navigation tracking. Note that the <code>state.navigation</code> properties are outdated and will be removed in a future version.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>André Maneiro</strong> rounds up <strong><a href=\"https://make.wordpress.org/core/2026/03/04/dataviews-dataform-et-al-in-wordpress-7-0/\">166 contributions from 35 authors landing in the DataViews space for WordPress 7.0</a>.</strong> Highlights include a new <code>activity</code> timeline layout, expanded field validation rules, a <code>combobox</code> control for large datasets, and a <code>groupBy</code> object replacing the old <code>groupByField</code> string — a breaking change worth noting. DataForm gains a new <code>details</code> layout and collapsible card controls. A lot here for plugin developers building data-rich admin interfaces.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Miguel Fonseca</strong> documents one of the most warmly received 7.0 additions: <strong><a href=\"https://make.wordpress.org/core/2026/03/03/php-only-block-registration/\">PHP-only block registration</a>.</strong> Pass <code>\'autoRegister\' =&gt; true</code> in the <code>supports</code> array alongside a <code>render_callback</code>, and your block appears in the editor without a single line of JavaScript. WordPress automatically generates Inspector Controls for supported attribute types — string, integer, boolean, and enum. Implemented by Ricky Pena, the comments section alone tells you how long PHP-first developers have been waiting for this one.</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Ryan Welcher</strong> and <strong>Ciprian Popescu</strong> went deeper on this topic and provided you with examples and explanations on their personal blogs. (See links below.)  </p>\n\n\n\n<div class=\"wp-block-group has-light-background-background-color has-background\"><div class=\"wp-block-group__inner-container is-layout-constrained wp-block-group-is-layout-constrained\">\n<p class=\"wp-block-paragraph\"><img alt=\"🎙\" class=\"wp-smiley\" src=\"https://s.w.org/images/core/emoji/17.0.2/72x72/1f399.png\" style=\"height: 1em;\" /> The latest episode is <a href=\"https://gutenbergtimes.com/podcast/gutenberg-changelog-127-wordpress-7-0-beta/\">Gutenberg Changelog #127 – WordPress 7.0 Beta and Gutenberg 22.6</a> with special guest <strong>Jessica Lyschik</strong>, senior developer at Greyd</p>\n\n\n\n<figure class=\"wp-block-image size-full is-style-no-vertical-margin\"><img alt=\"Jessica Lyschik and Birgit Pauli-Haack recording Gutenberg changelog episode number 127\" class=\"wp-image-44548\" height=\"184\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2026/02/Screenshot-2026-02-27-at-12.47.56.png?resize=652%2C184&#038;ssl=1\" width=\"652\" /></figure>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-rich is-provider-pocket-casts wp-block-embed-pocket-casts\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div></div></div>\n\n\n\n<p class=\"wp-block-paragraph\">In the video, <a href=\"https://www.youtube.com/watch?v=znVzVZ0jM9g\"><strong>7.0 Beta, Gutenberg 22.5, Studio &amp; AI: WordPress for Developers in February</strong></a> <strong>Ryan Welcher</strong> walks you through the February edition of the round-up series What&#8217;s new for Developers. You&#8217;ll get the highlights from Gutenberg 22.4 and 22.5: per-instance custom CSS, viewport-based block visibility, anchor support for dynamic blocks, and the long-awaited removal of extra editor wrapper divs. The iFrame enforcement planned for 7.0 has been delayed — more breathing room, but time to prepare is now.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">WordPress lead developer <strong>Dion Hulse</strong> has shipped something quietly useful: <strong><a href=\"https://www.therepository.email/wordpress-org-now-serves-markdown-output-for-ai-agents-and-developers\">WordPress.org now serves clean Markdown output</a> </strong>for every page, built on Dennis Snell&#8217;s html-to-md plugin. You can access it by appending <code>?output_format=md</code> to any URL or sending an <code>Accept: text/markdown</code> header. The efficiency gains are real — one developer reported a WordPress docs page shrinking from 68k tokens to 11k. It&#8217;s a direct response to Mullenweg&#8217;s push to make WordPress.org a canonical knowledge source for AI agents. <em>Ray Morey reporting for The Repository</em></p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\">In this brief video, <strong>Jonathan Bossenger</strong> demonstrates <a href=\"https://www.youtube.com/watch?v=OAYyx-qEpVY\"><strong>WordPress 7.0 Beta 2&#8217;s new WP AI Client and Connectors</strong> settings page</a>, explaining how connectors can install plugins and how developers can create AI features without tying users to a specific provider. A live CLI demo showcases this approach. Bossenger also discusses connector discovery UX and areas where core improvements are needed before 7.0 is released.</p>\n\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\">\n<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\n\n</div></figure>\n</div>\n\n\n<h2 class=\"wp-block-heading\" id=\"0-p\">Plugins, Themes, and Tools for #nocode site builders and owners</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress contributor <strong>Nick Hamze </strong>has quietly improved <strong><a href=\"https://www.therepository.email/the-wordpress-featured-plugins-tab-is-now-rotating-hidden-gems-every-two-weeks\">the Featured Plugins tab in wp-admin</a>,</strong> replacing a list that hadn&#8217;t changed in eight years with a rotating selection of eight lesser-known plugins, refreshed every two weeks. The goal, as <strong>Matt Cromwell</strong> reports for The Repository, is to surface genuinely promising newcomers — &#8220;not the giants, not the household names&#8221; — that you&#8217;d never stumble across through search or popularity rankings. Early results are striking; Ollie Menu Designer tripled its biggest download day within hours of appearing in the tab.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"2-word-press-6-0-1-and-6-1-scheduled\">Theme Development for Full Site Editing and Blocks</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Marko Ivanovic</strong> and <strong>Noam Almosnino</strong> shared their <a href=\"https://automattic.design/2026/03/03/telex-experiments/\"><strong>Telex experiments on the Automattic Design blog</strong></a>, showcasing what happens when designers get to build WordPress blocks by simply describing an idea. Telex, Automattic&#8217;s AI-powered tool, handles the technical wiring so you can focus on creative exploration. The pair built a text-scrambling interaction inspired by Flash-era pioneer Yugop and an image carousel—all without writing block code themselves. It&#8217;s a compelling glimpse at how your design-to-block workflow could change.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Derek Hanson</strong> shares how he shipped <a href=\"https://derekhanson.blog/tufte-blocks/\"><strong>Tufte Blocks</strong></a>, a WordPress block theme he couldn&#8217;t build a year ago, drawing on Edward Tufte&#8217;s typography-first aesthetic. After two failed attempts, the right combination — <em><a href=\"https://github.com/WordPress/agent-skills\">WordPress Agent Skills</a></em> and <strong>Shaun Andrews</strong>&#8216; <a href=\"https://shaunandrews.com/2026/02/teaching-ai-to-design/\">design-system-first</a> approach — finally unlocked it. You don&#8217;t need to be a designer or developer; Hanson&#8217;s project management and rhetoric background turned out to be exactly the right skills for directing AI through a complete, polished theme. Does it sound attractive to you? <a href=\"https://github.com/dhanson-wp/tufte-blocks\"><strong>Download it from GitHub</strong></a></p>\n\n\n<div class=\"ng-block-49800f1316915a24 wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div><div><div class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #fdfcea; border-radius: 12px;\"><div class=\"ng-block-f8a8df350f849a21 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong> <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/\" rel=\"noreferrer noopener\" target=\"_blank\">&#8220;Keeping up with Gutenberg &#8211; Index 2026&#8221;</a> </strong><br />A chronological list of the WordPress Make Blog posts from various teams involved in Gutenberg development: Design, Theme Review Team, Core Editor, Core JS, Core CSS, Test, and Meta team from Jan. 2024 on. Updated by yours truly. </p></div></div></div></div>\n\n<div class=\"ng-block-a18d9907a2e682e4 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p>The previous years are also available: <br /><strong><strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2020/\">2020</a> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2021/\">2021</a></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/keeping-up-with-gutenberg-index-2022/\">2022</a></strong></strong> | <strong><a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2023\">2023</a></strong> | <a href=\"https://make.wordpress.org/core/handbook/references/keeping-up-with-gutenberg-index/gutenberg-index-2024/\"><strong>2024</strong></a> </p></div></div></div></div></div><div class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></div></div><div><div class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div></div></div>\n\n\n<h2 class=\"wp-block-heading\" id=\"3-building-themes-for-fse-and-word-press\">Building Blocks and Tools for the Block editor.</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Ciprian Popescu </strong>walks you through <a href=\"https://getbutterfly.com/php-only-block-registration-in-wordpress/\"><strong>PHP-only block registration in WordPress</strong></a>, the new approach landing in 7.0 that lets you build Gutenberg blocks without JavaScript build tools. By setting <code>autoRegister</code> to true in the supports array, WordPress auto-generates inspector controls from your attributes and uses ServerSideRender for previews. You&#8217;ll find practical guidance on block supports, asset enqueueing caveats, and where this approach fits best—think author boxes, CTA banners, and theme-specific components rather than richly interactive blocks.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Ryan Welcher</strong> also explains how <a href=\"https://ryanwelcher.com/2026/03/04/php-only-block-registration-in-wordpress-7-0/\"><strong>PHP-only block registration in WordPress 7.0</strong></a> lets you skip <code>block.json</code> entirely and define block metadata directly in your <code>register_block_type()</code> call. You&#8217;ll see how to enable it with the <code>autoRegister</code> support flag, define attributes that auto-generate inspector controls, and wire up render callbacks with <code>get_block_wrapper_attributes()</code>. The tutorial covers asset registration via handle arrays and helps you streamline your workflow for server-rendered blocks ahead of the April 9 release.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Paulo Carvajal</strong>&#8216;s guide on <a href=\"https://wp-block-editor.com/mastering-event-handling-and-dom-interactions/\"><strong>mastering event handling and DOM interactions with the Interactivity API</strong></a> takes you through the <code>data-wp-on</code> directive for declarative event management. You&#8217;ll learn how to handle mouse, keyboard, form, and touch events while connecting them to store actions that update state reactively. The piece covers <code>withSyncEvent()</code> for synchronous access, automatic event delegation, and performance patterns like debouncing and throttling, wrapping up with a complete to-do app that ties it all together.</p>\n\n\n\n<h2 class=\"wp-block-heading\" id=\"ai-and-wordpress\">AI and WordPress </h2>\n\n\n\n<p class=\"wp-block-paragraph\">If you use Cursor for WordPress block development, <strong>JuanMa Garrido</strong> explains <a href=\"https://juanma.codes/2026/02/24/how-to-enable-json-schema-validation-in-cursor/\"><strong>how to enable JSON schema validation in Cursor</strong></a>, which is disabled by default due to a security vulnerability where the AI agent could trigger outbound requests via <code>$schema</code> fields. You&#8217;ll need to add <code>json.schemaDownload.enable</code> to your settings—ideally at the project level in <code>.vscode/settings.json</code> to limit exposure. A quick fix that restores autocompletion and validation for your <code>block.json</code> and <code>theme.json</code> files.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n<div class=\"ng-block-820e377d67f6243d wp-block-newsletterglue-container ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div class=\"ng-block-vs ng-block-vs-1\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div><div><div class=\"ng-block-hs ng-block-hs-1\" height=\"0\" style=\"width: 0px;\"></div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 20px; padding-bottom: 20px; padding-left: 0px; padding-right: 0px; text-align: none; color: #666666; background-color: #f8f8f8; border-radius: 8px;\"><div class=\"ng-block-615530f38c8d1898 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong><a href=\"https://gutenbergtimes.com/need-a-zip-from-master/\">Need a plugin .zip from Gutenberg&#8217;s master branch?</a></strong><br />Gutenberg Times provides daily build for testing and review.</p></div></div></div></div>\n\n<div class=\"ng-block-4ee6af9860cce03e wp-block-newsletterglue-image ng-block size-full is-resized\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 0px; padding-bottom: 0px; padding-left: 0px; padding-right: 0px;\"><a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\"><img alt=\"\" class=\"wp-image-42874 ng-image\" height=\"45\" src=\"https://i0.wp.com/gutenbergtimes.com/wp-content/uploads/2024/02/Screenshot-2025-11-15-at-12.06.44.png?resize=196%2C45&#038;ssl=1\" style=\"border-style: none; border-color: transparent;\" width=\"196\" /></a></div></div></div></div>\n\n<div class=\"ng-block-171b2f73d62e6776 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 16px; font-family: Helvetica; line-height: 1.6; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p>Now also available via <a href=\"https://playground.wordpress.net/?blueprint-url=https://gutenbergtimes.com/wp-content/uploads/2020/11/playnightly.json\">WordPress Playground</a>. There is no need for a test site locally or on a server. Have you been using it? <a href=\"mailto:pauli@gutenbergtimes.com\">Email me </a>with your experience.</p></div></div></div></div></div><div class=\"ng-block-hs ng-block-hs-2\" height=\"0\" style=\"width: 0px;\"></div></div><div><div class=\"ng-block-vs ng-block-vs-2\" colspan=\"3\" height=\"0\" style=\"height: 0px;\"></div></div></div></div>\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\"><em>Questions? Suggestions? Ideas? </em><br /><em>Don&#8217;t hesitate to send <a href=\"mailto:pauli@gutenbergtimes.com\">them via email</a> or</em><br /><em> send me a message on WordPress Slack or Twitter @bph</em>.</p>\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity\" />\n\n\n\n<p class=\"has-text-align-center has-small-font-size wp-block-paragraph\">For questions to be answered on the <a href=\"http://gutenbergtimes.com/podcast\">Gutenberg Changelog</a>, <br />send them to <a href=\"mailto:changelog@gutenbergtimes.com\">changelog@gutenbergtimes.com</a></p>\n\n\n<div class=\"ng-block-b5772f0eba9ac250 wp-block-newsletterglue-separator ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"center\" class=\"ng-block-td\" style=\"padding-top: 20px; padding-bottom: 20px; padding-left: 20px; padding-right: 20px; color: #666666;\"><hr style=\"background-color: transparent; color: transparent; margin: 0; border: 0; border-top: 1px solid #666666; width: 560px; height: 0;\" /></div></div></div></div>\n\n<div class=\"wp-block-newsletterglue-showhide ng-block\" width=\"100%\"><div class=\"ng-block-d5f32a5d7a1f46a5 wp-block-newsletterglue-text ng-block\" style=\"color: #666666;\" width=\"100%\"><div><div><div align=\"none\" class=\"ng-block-td\" style=\"font-size: 14px; font-family: Helvetica; line-height: 0.2; font-weight: normal; padding-top: 8px; padding-bottom: 10px; padding-left: 20px; padding-right: 20px; text-align: none; color: #666666;\"><p><strong>Featured Image: </strong></p></div></div></div></div></div>\n\n\n\n\n<hr class=\"wp-block-separator has-alpha-channel-opacity is-style-wide\" />\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 08 Mar 2026 09:53:07 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:18:\"Birgit Pauli-Haack\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:5;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:37:\"Matt: Declaration of the Independence\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:23:\"https://ma.tt/?p=151384\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://ma.tt/2026/03/declaration/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:639:\"<blockquote class=\"wp-block-quote is-layout-flow wp-block-quote-is-layout-flow\">\n<p class=\"wp-block-paragraph\">Governments of the Industrial World, you weary giants of flesh and steel, I come from Cyberspace, the new home of Mind. On behalf of the future, I ask you of the past to leave us alone. You are not welcome among us. You have no sovereignty where we gather.</p>\n</blockquote>\n\n\n\n<p class=\"wp-block-paragraph\">30 years a 1 month later, it seems like an apt time to revisit <a href=\"https://www.eff.org/cyberspace-independence\">John Perry Barlow&#8217;s Declaration of the Independence of Cyberspace</a>. The poetry is amazing.</p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Sun, 08 Mar 2026 07:57:11 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:4:\"Matt\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:6;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:47:\"Open Channels FM: Open Channels FM v7.1 Release\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=1650246\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:54:\"https://openchannels.fm/open-channels-fm-v7-1-release/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:53:\"Changes for 7.1 You can view our full changelog here.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Fri, 06 Mar 2026 08:40:31 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:7;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:40:\"WordPress.org blog: WordPress 7.0 Beta 3\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:35:\"https://wordpress.org/news/?p=20098\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:56:\"https://wordpress.org/news/2026/03/wordpress-7-0-beta-3/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:5875:\"<p class=\"wp-block-paragraph\">WordPress 7.0 Beta 3 is available for download and testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>This beta version of the WordPress software is still under development</strong>. Please do not install, run, or test this version of WordPress on production or mission-critical websites. Instead, you should evaluate Beta 3 on a test server and site.WordPress 7.0 Beta 3 can be tested using any of the following methods:</p>\n\n\n\n<figure class=\"wp-block-table\"><table class=\"has-fixed-layout\"><tbody><tr><td><strong>Plugin</strong></td><td>Install and activate the <a href=\"https://wordpress.org/plugins/wordpress-beta-tester/\">WordPress Beta Tester</a> plugin on a WordPress install. (Select the “Bleeding edge” channel and “Beta/RC Only” stream.)</td></tr><tr><td><strong>Direct Download</strong></td><td>Download the <a href=\"https://wordpress.org/wordpress-7.0-beta3.zip\">Beta 3 version (zip)</a> and install it on a WordPress website.</td></tr><tr><td><strong>Command Line</strong></td><td>Use this <a href=\"https://make.wordpress.org/cli/\">WP-CLI</a> command: <br /><code>wp core update --version=7.0-beta</code>3</td></tr><tr><td><strong>WordPress Playground</strong></td><td>Use the <a href=\"https://playground.wordpress.net/?php=8.0&amp;wp=beta&amp;networking=no&amp;language=&amp;multisite=no&amp;random=y4q1rn88xn\">WordPress Playground instance</a> to test the software directly in your browser.  No setup is required – just click and go! </td></tr></tbody></table></figure>\n\n\n\n<p class=\"wp-block-paragraph\">The scheduled final release date for WordPress 7.0 is <strong>April 9, 2026</strong>.  The full <a href=\"https://make.wordpress.org/core/2026/02/12/wordpress-7-0-release-party-schedule/\">release schedule can be found here</a>. Your help testing Beta and RC versions is vital to making this release as stable and powerful as possible. Please continue checking the <a href=\"https://make.wordpress.org/core/\">Make WordPress Core blog</a> for <a href=\"https://make.wordpress.org/core/tag/7-0\">7.0-related posts</a> in the coming weeks for more information. Thank you to everyone who is contributing with testing!</p>\n\n\n\n<p class=\"wp-block-paragraph\"><strong>Catch up on what’s new in WordPress 7.0</strong>: Read the <a href=\"https://wordpress.org/news/2026/02/wordpress-7-0-beta-2/\">Beta 2 announcement</a> for details and highlights.</p>\n\n\n\n<h2 class=\"wp-block-heading\">How to test this release</h2>\n\n\n\n<p class=\"wp-block-paragraph\">Your help testing the WordPress 7.0 Beta 3 version is key to ensuring everything in the release is the best it can be. While testing the upgrade process is essential, trying out new features is equally important. This <a href=\"https://make.wordpress.org/test/2026/02/20/help-test-wordpress-7-0/\">detailed guide</a> will walk you through testing features in WordPress 7.0.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you encounter an issue, please report it to the <a href=\"https://wordpress.org/support/forum/alphabeta/\">Alpha/Beta area</a> of the support forums or directly to <a href=\"https://core.trac.wordpress.org/newticket\">WordPress Trac</a> if you are comfortable writing a reproducible bug report. You can also check your issue against a list of <a href=\"https://core.trac.wordpress.org/tickets/major\">known bugs</a>.Curious about testing releases in general? Follow along with the <a href=\"https://make.wordpress.org/test/\">testing initiatives in Make Core</a> and join the <a href=\"https://wordpress.slack.com/messages/core-test/\">#core-test channel</a> on <a href=\"https://wordpress.slack.com/\">Making WordPress Slack</a>.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Beta 3 updates and highlights</h2>\n\n\n\n<p class=\"wp-block-paragraph\">WordPress 7.0 Beta 3 contains more than 148 updates and fixes since the Beta 2 release, including 70 in the Editor and 78 in Core. </p>\n\n\n\n<p class=\"wp-block-paragraph\">Each beta cycle focuses on bug fixes, and more are on the way with your help through testing. You can browse the technical details for all issues addressed since Beta 2 using these links:</p>\n\n\n\n<ul class=\"wp-block-list\">\n<li><a href=\"https://github.com/WordPress/gutenberg/commits/wp/7.0?since=2026-02-26&amp;until=2026-03-05\">GitHub commits for 7.0 </a> since February 26, 2026</li>\n\n\n\n<li><a href=\"https://core.trac.wordpress.org/query?status=closed&amp;changetime=02%2F26%2F2026..03%2F05%2F2026&amp;milestone=7.0&amp;col=id&amp;col=milestone&amp;col=owner&amp;col=type&amp;col=priority&amp;order=id\">Closed Trac tickets for 7.0</a> since February 26, 2026</li>\n</ul>\n\n\n\n<p class=\"wp-block-paragraph\">Tapping into the power of AI is even easier in Beta 3! The WP AI Client Connectors screen now dynamically registers providers from the WP AI Client registry, in addition to the 3 default providers, giving users more flexibility and command over AI integrations.</p>\n\n\n\n<h2 class=\"wp-block-heading\">A Beta 3 haiku</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Through sun set and rise,</em></p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Beta 3 takes off and flies.</em></p>\n\n\n\n<p class=\"wp-block-paragraph\"><em>Seven soon arrives.</em></p>\n\n\n\n<p class=\"has-text-align-right wp-block-paragraph\"><em>Props to <a class=\"mention\" href=\"https://profiles.wordpress.org/annezazu/\"><span class=\"mentions-prefix\">@</span>annezazu</a></em>, <em><a class=\"mention\" href=\"https://profiles.wordpress.org/jeffpaul/\"><span class=\"mentions-prefix\">@</span>jeffpaul</a></em>, <em><a class=\"mention\" href=\"https://profiles.wordpress.org/chaion07/\"><span class=\"mentions-prefix\">@</span>chaion07</a></em>,<em> <a class=\"mention\" href=\"https://profiles.wordpress.org/audrasjb/\"><span class=\"mentions-prefix\">@</span>audrasjb</a> and <a class=\"mention\" href=\"https://profiles.wordpress.org/valentingrenier/\"><span class=\"mentions-prefix\">@</span>valentingrenier</a> for proofreading and review.</em></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 05 Mar 2026 14:47:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:10:\"Amy Kamala\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:8;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:65:\"Open Channels FM: Why Design Systems Matter for Brand Consistency\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=1650119\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:72:\"https://openchannels.fm/why-design-systems-matter-for-brand-consistency/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:145:\"Consistency in digital branding through design systems fosters user trust, ensures quality, and supports scalable growth and clear communication.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 05 Mar 2026 13:59:18 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:9;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:78:\"Open Channels FM: Navigating the Future of Partnerships and AI in the Open Web\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=1650459\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:85:\"https://openchannels.fm/navigating-the-future-of-partnerships-and-ai-in-the-open-web/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:232:\"Zach Stepek and Carl Alexander discuss the changing landscape of partnerships and web development communities, emphasizing the importance of collaboration, genuine support, and the impact of AI on sustainable business relationships.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Thu, 05 Mar 2026 11:49:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:10;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:73:\"WPTavern: #207 – Rob Ruiz on WP Rig and the Future of Theme Development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:48:\"https://wptavern.com/?post_type=podcast&p=202950\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:87:\"https://wptavern.com/podcast/207-rob-ruiz-on-wp-rig-and-the-future-of-theme-development\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:61064:\"<details>Transcript<div>\n<p class=\"wp-block-paragraph\">[00:00:19] <strong>Nathan Wrigley:</strong> Welcome to the Jukebox Podcast from WP Tavern. My name is Nathan Wrigley.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Jukebox is a podcast which is dedicated to all things WordPress. The people, the events, the plugins, the blocks, the themes, and in this case the future of theme development.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;d like to subscribe to the podcast, you can do that by searching for WP Tavern in your podcast player of choice, or by going to wptavern.com/feed/podcast, and you can copy that URL into most podcast players.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you have a topic that you&#8217;d like us to feature on the podcast, I&#8217;m keen to hear from you and hopefully get you, or your idea, featured on the show. Head to wptavern.com/contact/jukebox, and use the form there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So on the podcast today, we have Rob Ruiz. Rob has been involved in the WordPress ecosystem since around 2010. He began as a designer, but over the years WordPress has helped him transition into a developer, software engineer, and now an architect. Currently, he&#8217;s working full-time at an agency whilst taking on side projects independently.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The main topic for today&#8217;s conversation, centers around themes, a subject that hasn&#8217;t been covered in depth on the podcast for quite some time. You see, Rob is the current custodian of WP Rig, a free and open source toolkit for WordPress theme development. WP Rig offers a modern, minimal, and best practice driven starting point for developers who want to build custom themes. Providing tools like Composer and Node integration to streamline workflows, enforce coding standards, and enable the use of future facing CSS features, right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We start the episode with Rob sharing what attracted him to WP Rig, and his journey from user to Project Maintainer. We talk about who WP Rig is for, from experienced developers, to those just starting to dip their toes into theme building and code customization.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion moves on to talking about what a theme development framework actually is, and why this approach might suit people wanting more control, and education, in their WordPress journey. Rob describes the learning curve, the workflow, and the satisfaction of creating your own theme from scratch, while highlighting tools and guardrails built into WP RIG that make professional standards and best practices accessible to all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into how WP Rig fits into the changing WordPress ecosystem. With the advent of full site editing and block-based themes, Rob explains how WP Rig has evolved to stay relevant, supporting classic, hybrid, and block-based paradigms, even enabling block development at the theme level.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end, we discuss the community behind WP Rig, how you can get involved, and the many educational resources available for those who want to learn theme development, or even become contributors themselves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in building custom WordPress themes, want to understand the nuts and bolts of theme frameworks, or are simply looking for a modern and educational starting point for WordPress tinkering, this episode is for you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you&#8217;re interested in finding out more, you can find all of the links in the show notes by heading to wptavern.com/podcast, where you&#8217;ll find all the other episodes as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so without further delay, I bring you, Rob Ruiz.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I am joined on the podcast by Rob Ruiz. Hello, Rob.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:56] <strong>Rob Ruiz:</strong> Hi. How are you, Nathan?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:03:57] <strong>Nathan Wrigley:</strong> Rob&#8217;s joining me today to talk primarily about themes, which I confess is a subject that we haven&#8217;t touched in a good long while. So before we get into that, Rob, would you just mind spending a minute just letting the listeners know who you are? If we are on a WordPress podcast, probably better to align that with what your journey is in the WordPress space, if that&#8217;s okay.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:17] <strong>Rob Ruiz:</strong> Certainly. Yeah. So my name is Rob Ruiz. I&#8217;ve been leveraging WordPress since about 2010 ish, although my web development experience goes prior to that. And so I&#8217;ve been tinkering and getting more and more into it as I go along.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I started off as mostly a designer back in the early two thousands, I guess. And WordPress has facilitated my journey from being a designer to more of a developer, software engineer, today, architect. And so yeah, it&#8217;s been a very fun journey. I&#8217;ve learned so much over the years, so I&#8217;m very grateful to WordPress for helping me do that at my own pace.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:04:58] <strong>Nathan Wrigley:</strong> Do you work for yourself? Are you perhaps engaged in an agency or something like that?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:02] <strong>Rob Ruiz:</strong> So currently, right now I work full-time at an agency, but I do also do work for myself as well. So it&#8217;s kind of a hybrid situation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:05:09] <strong>Nathan Wrigley:</strong> Okay, so the reason that Rob is on the podcast today, well, there&#8217;s a variety of reasons. Most of it will bind itself to the subject of themes, as I said right at the start. But we&#8217;re also going to be talking, maybe towards the end a little bit about AI and things like that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">However, Rob is now the custodian. I didn&#8217;t realise he was now the custodian. We&#8217;ll get into that in a minute. But Rob is the custodian at the moment of a project called WP Rig. And you can find this, it&#8217;s a really quick URL to type in, it&#8217;s WP Rig, so WPRIG .io.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Completely free to download, completely unencumbered by a pricing page or anything like that. There&#8217;s a GitHub repo I think. Yes, that&#8217;s right. So do you just want to give us the elevator pitch for what WP Rig is. And just because it makes me happy, can you tell us how you got involved? Because that&#8217;s lovely too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:06:00] <strong>Rob Ruiz:</strong> Yeah. Yeah, for sure. So WP Rig is a theme development toolkit or framework, but it&#8217;s also a starter theme as well. So you could think of it as kind of like underscores but with a whole modern development toolkit situation built into it, meaning there&#8217;s a bunch of composer dependencies, Node dependencies, and other kind of developer tools baked into it to prepare developers for the best developer experience possible when developing themes for WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How I got involved with it essentially is I was, first off, I was looking for a theme development framework. I had gone on a journey to explore many. And during that journey, I came across WP Rig, and kind of fell in love with it. It was really, really cool. I liked it a lot. I liked a lot of the opinions. I liked how well aligned it was with Core WordPress itself. I like the WordPress best practices that it enforces, you know, automatically. You don&#8217;t even have to like go look them up and think about it. You could just run a tool that&#8217;s built into it and it&#8217;ll check all your code for said best practices.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so that was very interesting to me. I was like, I&#8217;m going to start using this. And so I did. I did start using it. And then, shortly thereafter, I had been browsing my favorite WordPress news site, WP Tavern, and noticed an interesting article about the project that I had just recently fell in love with out of sheer coincidence, I suppose. Out of sheer coincidence, it just so happens this project is now looking for new maintainers, and that they were having a Zoom call in the near future where anybody interested in maintaining the project could join the Zoom call.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so I did. I joined the Zoom call and I got to meet the previous maintainers, or maintainer rather, and ended up having ongoing conversations with him after the call. And one thing led to another, and now the project is basically managed solely by me with a handful of other light contributors.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:04] <strong>Nathan Wrigley:</strong> So that&#8217;s really nice. I love the fact that there&#8217;s some sort of combination of WP Tavern and WP Rig out there. That&#8217;s lovely. So I appreciate that. The audience for this podcast is pretty varied. So there&#8217;ll be developers with a longstanding history with WordPress, you know, deep in the code. Will go to WP Rig and immediately everything will connect, and they&#8217;ll be like, yep, I get this. I understand what this is. It&#8217;s for me. It&#8217;s not for me, yada, yada.</p>\n\n\n\n<p class=\"wp-block-paragraph\">However, we also have quite a lot of people listening to this who are brand new to WordPress. They&#8217;ve got no experience with code. They may be living inside of a page builder or something like that where everything is point, click, drag, drop, save, that kind of an environment. It just occurred to me that they very well might not know what even a theme development framework is. So can we begin there? What is the point of a thing like this? What&#8217;s the problem you&#8217;re trying to solve? Let&#8217;s start there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:08:53] <strong>Rob Ruiz:</strong> Yeah, that&#8217;s a great question. So like anything in WordPress, because it&#8217;s open source and so beautifully designed, might I add, from an architectural standpoint, there are lots of ways to extend WordPress beyond its base functionality.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Two of the most common ways to do this is via the plugin system, and via the theme system. And so we can add custom plugins to extend the functionality of WordPress, but we can also add custom themes to alter the way our website looks and feels aesthetically.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if you&#8217;re somebody who&#8217;s more of a designer maybe, or you appreciate aesthetics and perhaps you&#8217;ve dabbled in some CSS, you might be more inclined, if you&#8217;re looking to go beyond just what Core WordPress provides to you in terms of a site building experience, I would encourage those people to look at themes and possibly creating your own custom theme. Or altering an existing theme using a concept called child theming where you can take any theme that you get from anywhere, whether you buy it or find it on the wordpress.org theme repository. You can extend themes using child themes, or you can just build your own themes from scratch.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that does include some work outside of the WordPress admin area. So once you get into developing themes for WordPress, the concept here is you&#8217;re kind of straying away from the WordPress admin experience, and you&#8217;re now like in the code editor realm, right? Because under the hood, WordPress is all just a bunch of code, PHP, JavaScript, CSS. There&#8217;s a lot going on, the React now. There&#8217;s a lot of things kind of built into WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so the beautiful thing about WordPress is that you can kind of, if you&#8217;re interested in learning how to develop, you can kind of dip your toes into the development pool as frequently as possible, as quickly as you want. Whatever you are comfortable with, you can kind of pace yourself there and say, okay, let me try and make a custom theme, or let me try to make a custom plugin. And if it doesn&#8217;t work out, it&#8217;s easy to just deactivate it, delete it, remove it, whatever. It&#8217;s a great way to learn how to develop, in my personal opinion, because a lot of the heavy lifting is done by the Core WordPress system.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Basically what WP Rig offers is, instead of having to create a file system, a theme system from scratch, you know, a lot of people will reach for a concept called a boilerplate. Something that will scaffold kind of like the common files and folders that would be necessary in a theme, and then allow you to work from there. So you&#8217;re not just starting from like ground zero, create a new directory, create a new file.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so that&#8217;s kind of what WP Rig offers is like, okay, go to our GitHub repo, clone the GitHub repo down, and then there are directions in the repo on how to get it to scaffold all the tools that come with it, all of the Node and Composer tools. And then you&#8217;re kind of off to the races.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:11:46] <strong>Nathan Wrigley:</strong> So with WP Rig, I&#8217;m guessing we would describe this as a framework or something like that. The idea being that you can bring this, kind of learn how it works, become adept at it, and then it&#8217;s like your constant friend. It&#8217;s always in the background. It&#8217;s the thing that you can rely on. It&#8217;s the muscle memory which develops over time. So you can ship your own themes, which kind of depend on the framework, but also, you know, you&#8217;re familiar with it so that bit is taken care of and straightforward.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What is it that attracted you to this particular theme development framework, at the time when you were sort of scrambling around looking for a project to become involved with?</p>\n\n\n\n<p class=\"wp-block-paragraph\">I mean, one of the things that I always found curious was the leaner, the better. You know, the less that there was in such a thing, the more I was drawn towards it, because it gave me a, the basis, the scaffolding basically from which I could start building. Now, I don&#8217;t know if that&#8217;s what drew you here. So there&#8217;s the question. What is it that you thought was superior for want of a better word about this one?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:12:41] <strong>Rob Ruiz:</strong> Well, you nailed it. It&#8217;s really that. Like, it is quite minimal at its core. I also really appreciated how it treated CSS, as somebody who comes from a design background. I love modern CSS. I love following CSS influencers on YouTube, and learning all the new tricks. It&#8217;s a lot to keep up with and as, now that Internet Explorer is gone, CSS is progressing at an enormous rate, which I&#8217;m very excited about. But it also forces you to keep in tune with what you can do with it and what you shouldn&#8217;t do with it. And so there are tools built into WP Rig to help you assess those things as you&#8217;re developing your CSS in there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When I originally was brought onto it, we were using a tool called PostCSS. That would essentially allow you to use future CSS before it was adopted by all modern browsers. And during the compilation process, it would convert your future CSS to today CSS essentially. And so the idea there is that as CSS catches up, your compilation would just have to do less work, right? So when it compiles all your CSS, it would, you know, like now that nesting is a thing, right? I was using WP Rig before CSS nesting was supported by all modern browsers, but I was able still to use CSS nesting in WP Rig, which I really liked. So there&#8217;s that aspect of things</p>\n\n\n\n<p class=\"wp-block-paragraph\">and yes, it is very light. I&#8217;ve used other theme development frameworks where they encourage you to use kind of like a templating language or framework. I didn&#8217;t really like that approach because it felt very foreign to WordPress. Nothing else in WordPress uses such a thing. That kind of turned me off a little bit because I was like, I don&#8217;t want to learn this whole other concept that like really doesn&#8217;t exist anywhere except for Laravel. I liked that about it. It kept it simple in that regard.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then if you&#8217;re using WordPress at like a agency level, if you&#8217;re building bespoke custom sites for clients, something like WP Rig is extremely powerful because it allows you to increase your level of customisation as much as you want, and the tools are all there to help you handle that. Also, meanwhile, if you&#8217;re working on a team of developers, which is often the case if you&#8217;re working with an agency or something like that, WP Rig becomes kind of like a home base, if you will, for opinions, for coding practices, for checks and balances.</p>\n\n\n\n<p class=\"wp-block-paragraph\">All these things, it helps put everybody on the same vehicle, I guess, if you want to think of it like that. Everybody&#8217;s using the same vehicle, so there&#8217;s not wildly different ways of doing things, which can be very, very handy when working on a team and assessing other people&#8217;s code, and perhaps taking over work for other people and so on and so forth.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:15:23] <strong>Nathan Wrigley:</strong> So the thing about frameworks, I guess, is that, if you are in the WordPress space and you are that page builder user, so everything is within the WP admin, you know, you download a plugin, which creates pages or a theme, I guess you could do the same thing, but you&#8217;ve got that kind of experience with WordPress. Is this something that would map to those kind of users perfectly, or is there more of a learning curve? Do you need to be leaning more into the developer side of things?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Maybe there&#8217;s a happy transition that can be made. Because, you know, when you&#8217;re on the website, you have interesting acronyms. So, you know, CSS, JS, we&#8217;re probably entirely familiar with those, but then we get into things like esbuild, Lightning CSS, ESLint, NPM, Composer and so on. And at this point I can imagine quite a few of the inexperienced users thinking, you know what, this is going to be tough for me.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So I just want you to give us an impression, reassure people. How hard is it to go from that, I&#8217;ve never done anything like this before. To up and running, becoming familiar, if not necessarily completely familiar in a heartbeat?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:16:25] <strong>Rob Ruiz:</strong> In my opinion, it&#8217;s not hard because you can kind of just focus on where you want to focus. And so for instance, if you&#8217;re only interested in writing CSS styles and you just want to change colors, and sizing, and fonts, and stuff like that, you could use WP Rig to make an extremely simple theme, which is what I would encourage people to do if they&#8217;re just getting up and running.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Back to your question about page builders and such, there is like this, I don&#8217;t want to call it a problem, but there is a paradigm in WordPress that I think, especially for newer WordPress developers, they need to be very aware of, which is that you kind of have two schools of thought.</p>\n\n\n\n<p class=\"wp-block-paragraph\">You have this school of thought of like, okay, I want to just use the WordPress admin to customise every little bit, every little piece of my WordPress site. I should be able to do it in the WordPress admin. And so that&#8217;s where some of these more complex page builders kind of come in and provide a lot more control than just what Core WordPress provides you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But with that said, it will never be ultimate control. It will never be ultimate control, because there&#8217;s always going to be some amount of constraints. You&#8217;re always going to be constrained by what configurations, what settings, what fields, what controls that page builder provides you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And not only that, you have to keep in mind some of these rules, I like to think of them as rules, configurations, settings, whether it&#8217;s at the block level, widget level, element level, whatever word you want to use to describe a part of your page, like an object or a component, it&#8217;s a very common word. When you&#8217;re using a page builder, that&#8217;s all getting saved into the database. Anytime you enter a value, you click save or whatever. Everything is in the database, all of it, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so if you need to make a global change across your whole site, let&#8217;s say you want all of the blocks on your website to all of a sudden have a border around them, or you want to change something about them, the colour, background colour, something like that. In a page builder world, you&#8217;re going to have to go into every single one of those elements, those blocks, whatever, and you&#8217;re going to have to change those values everywhere.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Where, when you&#8217;re doing things with just code, you have kind of superpowers. In my opinion, coding, if you want ultimate control over your site and you want to be able to do literally anything you can imagine, and be able to do it in a way that&#8217;s progressive and is comprehensive, without any barriers, without any limitations, code will always be the best way to exercise that control that you&#8217;re going after.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, obviously, newer people, too much control can lead to confusion and all this stuff. So I don&#8217;t fault people for using some of these other solutions like page builders to kind of get their feet wet and get up and going and kind of figure out how to use just WordPress itself.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But once you get to a point where you&#8217;ve been doing that for a while and you&#8217;re looking at like other websites that aren&#8217;t even WordPress that have all kinds of interesting, cool features built into them, new paradigms being presented and exposed. Let&#8217;s say you follow CSS and you&#8217;re looking at all the newest CSS features that are coming out. Many of those newest CSS features that are coming out, there&#8217;s really no ability to control those things in your WordPress site, because that stuff literally just got adopted by Chrome or whatever, just reached modern browser adoption like recently, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so you have to kind of wait for the page builders, for WordPress to kind of now provide you new controls, new tools, so that you can then control those things. But when you&#8217;re doing things with code, you could just do it immediately, and you could do whatever you want.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So when you&#8217;re building your own theme from scratch or you&#8217;re trying to, even creating your own plugin from scratch, it&#8217;s never really going to be a concept that&#8217;s for like new WordPress people that are just very, very new to just developing websites in general. But it is nice to know that these tools are out there and they&#8217;re there, so that when you do get to a point where you&#8217;re ready to kind of spread your wings a little bit more, you know what tools are out there to reach for. And you can begin to play with them a little bit instead of forever feeling confined to one paradigm.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:20:40] <strong>Nathan Wrigley:</strong> Yeah, there is something exceedingly satisfying about understanding how, whatever the thing is works. I imagine that as a child, you were perhaps that child that took things apart and enjoyed the experience of looking at the insides and thinking, how did that work? Okay, that&#8217;s how it worked. Okay, that cogs connected to that thing, and then that spins around in that way. And, oh, and look that on the front spins around as well. Got it. I understand that now. And you reassemble it and what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I think there is something exceedingly interesting about that in the WordPress space. Obviously, WordPress, CMS, incredibly powerful out of the box. You&#8217;ve got the WP admin, and perhaps that&#8217;s as far as you wish to go.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But peeling back the layers and understanding, how is a page constructed? Where does the CSS get called from? How is the HTML finally output? What are the bits and pieces that make it up? How does the theme layer do its bits and pieces? You don&#8217;t have to kind of understand it all in one hit. You can, with a framework, the likes of which we&#8217;re talking about, WP Rig, there is this capacity to just take little nibbles and have a slow, but realising appreciation. Oh, okay, that&#8217;s how it works.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But not only that&#8217;s how it works, okay, now that I know how that works, I now am in control of it. Whereas in a way, previously, I just was sort of a passive observer. Perhaps there was a setting area in my page builder or what have you. And if it was there, I could make use of it, and if it wasn&#8217;t, I couldn&#8217;t.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also I think it drives you into that journey of understanding the open standards, the open web, the things that make up the technology which is free, available to everybody. What WordPress builds upon.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And I&#8217;m talking specifically about HTML, CSS and JavaScript, just those three things. The foundational pieces of the web. And it allows you to get involved in that, and be interested in that and understand where the web is heading. And especially like you said, with modern CSS&#8217;, it is coming really fast and it is fast replacing, in many respects, I think a lot of JavaScript really is going to be obsolete, for the front end side of things, in the fairly short term.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it allows you to sort of nibble away at that and become more experienced. And if you haven&#8217;t had that journey but you&#8217;ve got a curiosity, this is possibly a great place to start. There is no question there, but I&#8217;m just sort of offering that up to see if that jibes with what you think.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:22:52] <strong>Rob Ruiz:</strong> I couldn&#8217;t agree more. And not only that, I think an important thing to think about WordPress as we move forward into the future and more competitors to WordPress emerge, I think it has never been more important to make sure that we have tools out there that are designed to facilitate people in their journey to getting into development. Because let&#8217;s be real, WordPress is open source, and we have to remember that WordPress is at the mercy of its contributors.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so if the number of people contributing to WordPress starts to decline, so too will the progress of WordPress itself, unless other big companies with other developers that they&#8217;re actually paying are willing to foot the bill to like pay people to contribute to WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">I don&#8217;t know that that&#8217;s the bright future that WordPress had originally like looked towards, right? I think what&#8217;s made WordPress so powerful and so successful over the years are the tinkerers, are the people that are willing to get in there and start to like learn things and figure things out. And then those people will slowly become contributors. And the more contributors we have to WordPress, the more WordPress itself will flourish. And then if that starts to go in the opposite direction, so too will WordPress.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And now these other services, and other solutions that are out there, are going to like eclipse WordPress and then people are kind of forced into a situation where it&#8217;s like, oh, well now you have to constantly go out and pay for and buy things, and now you&#8217;re at the mercy of these product authors, if you will, as opposed to being a part of a community of people that are all kind of collectively working together to make this one platform better all the time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:24:37] <strong>Nathan Wrigley:</strong> Yeah, the open web and all of the web standards that are behind that, it is such an interesting time for that. Rewind the clock, I don&#8217;t know, 10 years or something, and there was this whole bond fight thing where browser vendors were just distributing things which were either in opposition, certainly in competition to features. And so you could never really figure out what the heck you were doing, and each browser would behave differently.</p>\n\n\n\n<p class=\"wp-block-paragraph\">That is so far in the rear view mirror now. In the majority of cases, new things like new CSS, the new CSS spec is broadly speaking, adopted by everybody out of the box. I mean, there might be a few tiny edge cases where, I don&#8217;t know, let&#8217;s say Mozilla is just not implementing something because they just haven&#8217;t quite got round to it yet.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But there&#8217;s no, Mozilla&#8217;s not doing that. It&#8217;s just a case of, we didn&#8217;t get around to it. And understanding that and being interested in that and thinking to yourself, well, goodness me, if I change my CMS of choice, at the end of the day, I still need to be able to output HTML and CSS. And so having that tinkerer mentality, which you are providing within the WordPress space is so interesting and so credible. So thank you for that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Right, I&#8217;m going to pivot a little bit. So again, this is leaning in more to the inexperienced user. Forgive me if you are an experienced user listening to this, you probably know what you are doing. So maybe, you know, you don&#8217;t need all the 101 stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What do you need to get WP Rig up and running? Because I think a lot of the audience listening to this will simply be, I have a server somewhere. You know, I don&#8217;t really know where it is, but I pay some company and I click a button in some control panel and WordPress magically happens. And then I install a theme and plugins, and that&#8217;s basically it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So what do we need to get WP Rig up and running? What are the core parts, the processes that we would need to go through?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:26:24] <strong>Rob Ruiz:</strong> Yeah, well the important thing to keep in mind here is that it&#8217;s all on your own computer that you&#8217;re doing all of the work, as opposed to the WP admin approach where, when you&#8217;re interacting with WordPress, you are actually interacting with a remote server. The databases on the remote server, the files are on the remote server, all that stuff.</p>\n\n\n\n<p class=\"wp-block-paragraph\">When you&#8217;re developing a theme or plugin from scratch, more often than not, I would say 99% of the time you&#8217;re doing it on your own computer. And so you do have to have, if you want these tools that facilitate this development process, you have to install them on your computer so that they&#8217;re available when you go to use them.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So there are some pre-reqs to using WP Rig. You do have to install Node. Node.js is a very common JavaScript runtime that runs on your computer and allows your computer to process JavaScript as if it&#8217;s a browser kind of, but it&#8217;s not, it&#8217;s just doing it on a server, which essentially any computer can be a server at any time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so you have to have Node installed. You have to have Composer installed. Composer is just a package manager for PHP, and it&#8217;s used beyond just WordPress. It&#8217;s used in Laravel. It&#8217;s used in any, even just raw, vanilla PHP development. Composer is very popular. So we do leverage some Composer packages to do some PHP level work in the theme.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And you need a local development environment, of course. So there&#8217;s the wp-env package out there. If you&#8217;re into the Docker way of doing local development. I&#8217;m a big fan of Local WP. I think that&#8217;s a great solution. WordPress Studio is another very good one. There&#8217;s lots to choose from out there.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So just choosing a local development environment and getting to know one of those is really handy because now you&#8217;re not dealing with a WordPress instance that&#8217;s on a remote server, you&#8217;re dealing with a WordPress instance that&#8217;s running on your computer. And this is where all of that magic is going to happen. All the automatic conversion of your CSS, all automatic conversion of TypeScript to ES5 JavaScript. All of the automatic things that WP Rig handles for you, all of that is happening on your computer.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And then there&#8217;s a process, a bundle process that happens. Once you&#8217;re done working on your theme, you can bundle the theme and then, this is where things get a little weird. So like when you first get working with WP Rig, you can think of the WP Rig theme, the starter theme as kind of like a source theme. But when you bundle, WP Rig actually generates a whole new theme for you that has the name of your theme baked into it. And not just like how it shows up in the WordPress admin, it goes through and it replaces all references to WP Rig in the code everywhere, across the entire code base of the theme. It changes the words WP Rig to whatever the name of your theme is.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if you build a theme with WP Rig and you decide to sell it or deploy it or ship it or whatever to anybody, user, wherever, anywhere. Anybody that&#8217;s looking through that source code, for whatever reason, they would have no way of knowing that it was built with WP Rig because it&#8217;s just going to look like your theme.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:29:31] <strong>Nathan Wrigley:</strong> There&#8217;s something extremely satisfying about seeing your theme. The first time you see your theme. Stick it on a website somewhere and, oh, look, there&#8217;s the thing that I built. Whereas, you know, for many people, it&#8217;s been an entire experience of going to the repo, going to commercial theme houses and what have you, and downloading something and tweaking it and what have you.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And you really can start really, really, really small. You know, a few lines is really all that you need to get going and build up from there. Obviously it will start plain, but the more complexity you add.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But given that it&#8217;s all happening on your local computer, it&#8217;s not like you need to rush. This could be something which is years in the making. You know, you start today and maybe two years from now you are entirely happy and you&#8217;ve got something that you think is worthy of the world looking at. Well, that&#8217;s the point at which you can start to distribute it. As you&#8217;ve just described, because it&#8217;s all free, completely open source, when you ship that theme, export it, everything is run in such a way that nobody would ever know, which is just lovely.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Okay, so given all of this fresh, interesting stuff about WordPress themes, we&#8217;re in an interesting space in the WordPress theme marketplace, let&#8217;s call it that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Several years ago, full site editing came along and now we&#8217;ve got this sort of different way of doing themes. Previously we had to open up an IDE and fiddle with template files and things like that. And now we&#8217;ve moved more into a page builder, let&#8217;s go with that. You know, there&#8217;s this Gutenberg block based editing of themes, where you can do more or less everything in a UI.</p>\n\n\n\n<p class=\"wp-block-paragraph\">How does this fit into that piece, and what do you make of this new paradigm, this new way of doing themes? Are there benefits to it that you see, or drawbacks? Are you still doing it? Do you see a bright future for WP Rig? I&#8217;m guessing the answer&#8217;s yes, otherwise you wouldn&#8217;t be on this podcast.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:31:16] <strong>Rob Ruiz:</strong> That&#8217;s right. Yeah. Well, I will say that as somebody who had recently decided to adopt WP Rig, when the whole concept of FSE was first announced or introduced, I did have some strong opinions because I was like, oh my gosh, this is going to make my life very difficult if this becomes the way of doing things. And so I kind of foresaw a lot of where things have gone over the past few years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So at the beginning I was a little hesitant because it kind of threw a wrench in this new thing that I was excited to adopt and start advancing. Over time I have come to appreciate it quite a bit. And in my opinion, it&#8217;s just allowed me as the maintainer of WP Rig, a lot of opportunity to really get in there and learn a lot, and get my hands dirty, and allow WP Rig to become something that was more my own, as opposed to something that I just adopted from some other people that had done a bunch of work, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">Had that not happened, I probably would&#8217;ve just been like encouraged to just kind of sit back and be like, ah, yeah, you know what, this is my thing and it works and whatever. But this presented a lot of challenges and those challenges present a lot of opportunity if you look at it the right way. Not just opportunity to make something my own, not just opportunity to build things, but also opportunity, most importantly, I think, to learn things. And so that&#8217;s really been the gift of where all of this has gone for me personally.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Do I think that full site editing makes it so that you don&#8217;t have to make your own theme as much? Yes, I do think that is a thing because you have a lot more control of the way your website looks from within the WordPress admin area and creating templates and block patterns and all that stuff from within WordPress. It is different than how we used to do it, let&#8217;s put it that way.</p>\n\n\n\n<p class=\"wp-block-paragraph\">However, as somebody who has decided to just like adopt it, I will say that if you can keep the paradigms and concepts all categorised and separated in your brain, then it&#8217;s actually quite powerful and can be extremely handy, especially with how fast the WordPress admin experience has gotten over the past few versions. It is very snappy now, almost to the point where it&#8217;s satisfying to use. Crazy to say. But it&#8217;s just so snappy. And we&#8217;ve got lots of little micro animations coming in there now where you can, you know, just the way everything happens is like, to me, it makes it a little bit more fun.</p>\n\n\n\n<p class=\"wp-block-paragraph\">What does that mean for WP Rig? Well, that means there&#8217;s multiple paradigms that WP Rig has to support. So because WP Rig was originally created in the classic paradigm, when you first start using WP Rig, it does assume that you&#8217;re creating a classic style theme. But that doesn&#8217;t mean you&#8217;re forced to build a classic style theme. Because one of WP Rig&#8217;s strongest features is that there are whole bunch of custom command line commands that you can type in and run that will automatically convert WP Rig into these other paradigms.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So if you want to build a block-based theme or a universal theme, which is kind of halfway between classic and block-based, you could just run a command in your terminal and it will just automatically change a bunch of files in WP Rig to convert it to this other paradigm. And now you have full site editing as part of your theme.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And many people may not be aware of this, but the whole concept of full site editing is controlled by the theme. Whether or not you even have full site editing on WordPress is dependent on the theme. It&#8217;s not well, Gutenberg can be removed via a plugin, but in order to enable these functionalities, like if you want to be able to do full site editing, it is the theme that dictates that, not a plugin.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it is important for WP Rig to facilitate that part of things. And so that is something that I&#8217;ve had to build out among many other things. Now WP Rig has a full block authoring experience built into it.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, this is where things get very, very opinionated among developers. But a lot of people argue that blocks are a, that&#8217;s plugin territory, right? Now, I don&#8217;t know about you, I&#8217;m not really much for territories. I like to pretend that borders don&#8217;t exist sometimes. And so there are situations where building theme level blocks do make sense. Keep in mind that if you decide to bake custom blocks into your theme, you have immediately disqualified yourself from contributing this theme to the wordpress.org theme repository. So keep that in mind. That&#8217;s a big cautionary, little tidbit.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But if this theme is just for you, or a client, or for usage outside of the WordPress repository, WordPress does have the ability to enable block authoring within WP Rig. And then now you can start to author blocks within your theme.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Where I like to think of this as like navigation, right? When I&#8217;m looking for themes, if I&#8217;m like shopping for themes, one of the first things I look at is, what is the navigation for this theme? What is that experience like? Because there&#8217;s lots of different kind of like styles of navigation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you need to create a custom navigation, maybe there&#8217;s a situation where the navigation block in Core WordPress doesn&#8217;t suit your needs for whatever reason. Maybe the design of what you&#8217;re trying to build somehow goes beyond what that block provides to you in terms of functionality. You could create your own custom navigation block, and in my opinion, that makes a lot of sense to be part of the theme as opposed to a plugin, right?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So there&#8217;s opinions there. Again, this is the nice thing about open source. There&#8217;s freedom there. But yeah, WP Rig has not just the ability to facilitate full site editing, but also the ability to facilitate block authoring at the theme level. So, yeah, one could look at this and be like, oh, this makes theme development kind of pointless because you could just do everything within the full site editor. I&#8217;m somebody that likes to kind of flip things on its head a little bit sometimes and say, actually, you know what that really means is that this gives the theme more control than perhaps you would&#8217;ve thought previously. And if you exercise said control, and if somebody provides an easy way to allow you to exercise that control, now we have a whole new paradigm. And in my opinion, that&#8217;s extremely interesting.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:37:39] <strong>Nathan Wrigley:</strong> Yeah, I think the thing that I&#8217;m taking away, well, there&#8217;s a few things from what you just said. The first one, fully hybrid. You know, it could be classic, it could be block based, or it could be somewhere in the middle, like this hybrid sort of approach, which doesn&#8217;t really get talked about all that much anymore, actually, which is curious. It was a big thing for a while, and now people seem to be on one side or the other. So there&#8217;s that.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But also the bit that I&#8217;m taking away from all of this is how much you are encouraging people to use this as an education piece. How to learn and scaffold your learning around something like the WP Rig project. It enables you to sort of peel back the layers. Start from a base of kind of nothing and build that up, slowly one piece at a time.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And your navigation is a really great example. You might have, I don&#8217;t know, maybe a client comes along who have proclivities around, it&#8217;s got to be 100%, we&#8217;ve got to give everything over on the accessibility side, we&#8217;ve really got to do that perfectly. Well, this maybe is a great place to start. You know, you start with a blank template for that, and you build your navigation. So you will end up exploring all sorts of documentation over on the W3C website. Probably not necessarily so much on the WordPress side of things. Figure out how to do that really well, import your knowledge that you&#8217;ve gained from that into the navigation aspect of WP Rig, ship that, you&#8217;re off to the races.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Now, with that in mind, if you go to the WP Rig website, there&#8217;s a lot of educational content there. So there&#8217;s the inevitable kind of getting started, which is what we talked about earlier, all of the packages and the package managers and what have you that you need to get up and running. So it explains how that is all to be done. Relatively straightforward to follow that through, I would&#8217;ve thought.</p>\n\n\n\n<p class=\"wp-block-paragraph\">But then entirely separate to that is two different sections. You&#8217;ve got this like learn section where you&#8217;ve got documentation, video tutorials and things like that. But then you&#8217;ve also got like the docs area where you go into explain, oh I don&#8217;t know, how you might use JavaScript or CSS or some sort of compiled CSS or PHP and so on and so forth.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So again, no question there really, but it does feel, from my point of view, looking at this project that education is kind of the big piece. That&#8217;s the thing that you are most interested in. I don&#8217;t know if I&#8217;ve misrepresented this project, but that&#8217;s what it feels like.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:39:58] <strong>Rob Ruiz:</strong> A hundred percent. And I think that&#8217;s inevitable when it comes to getting into this tinkerer mindset. There must be a way to learn how to tinker properly. It is also nice to add guardrails to said, because let&#8217;s be honest, there&#8217;s like a million different ways to do everything, but there&#8217;s very, very few correct ways to do everything.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so that&#8217;s another nice feature of WP Rig is that it has these sort of guardrails in place that allow you to check and make sure that you&#8217;re doing things properly. And if there&#8217;s anything that you&#8217;re doing improperly, you can obviously ignore those if you want to for whatever reason, or you can like dive into the weeds and say, okay, why is this improper?</p>\n\n\n\n<p class=\"wp-block-paragraph\">So for instance, WordPress, Automattic created a package. It&#8217;s essentially an extension for a tool called PHPCS, which stands for PHP Coding Standards. This tool is used by PHP widely beyond just WordPress. But then WordPress adopted it a while back and decided to use it and create their own extension for it called the WordPress Coding Standard. It&#8217;s WPCS.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so they&#8217;ve iterated on it over the years and WPCS is baked into WordPress, or into WP Rig rather. So if you want to make sure that your theme is following all of the WordPress coding standards for whatever reason, maybe it&#8217;s because you&#8217;re going to create a theme that you want to contribute to the wordpress.org theme repository, then that tool is baked into WP Rig for you, so that you can make sure that your theme meets all of the requirements for a properly developed theme before you even try to go and like submit it for a review or whatever.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Because that&#8217;s one of the most frustrating things ever is somebody who wants to contribute. If you try to contribute and then you get pushed back on, that&#8217;s like not a great experience. And so what I try to do with WP Rig is bake in this layer that is kind of like a, test it yourself type situation. Where you can kind of like have the system sort of, kind of review the code for you, and then that way you can make sure you&#8217;ve done your due diligence before you even try to submit it for review. To prevent that unfortunate situation where your theme might get rejected for one reason or another, and now you got to go back and rework it and then back and forth, back and forth, back and forth.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Having a tool like WP Rig that just tells you early on before you even try to submit it, hey, you should change this, you should change that. I think that&#8217;s extremely valuable for people. And again, I really want WP Rig to be something that encourages people to get more into contributing back into Core as opposed to. I mean, it can also be looked at as something like, okay, well you want to go develop your own thing and it&#8217;s for profit or whatever. It does very much facilitate that way of doing things too. But let&#8217;s be honest, anything that meets WordPress&#8217;s coding standards is probably going to make your theme, even if you&#8217;re putting it up for sale, it&#8217;s going to make it better.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:42:53] <strong>Nathan Wrigley:</strong> Yeah, I love that you&#8217;ve built all of that in. That&#8217;s really interesting. So it does a lot of the heavy lifting, trying to make sure that you are adhering to the standards, which one would hope would be in a shippable, distributable product.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Speaking of community, do you have a community which coalesce around this project? Is it basically just you? Or is there like a little team? And if not necessarily a team, is there a little community which gathers and sort of helps you put this project together? And a corollary to that question really is, do you anticipate in the future that you will like some contributors to help you maintain this as well?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:43:27] <strong>Rob Ruiz:</strong> Yeah, for sure. So when I first started, when I first adopted this as my own, there was more of a team in place because Morten is a very well-known individual. And so he had a lot of followers and so a lot of those followers had followed WP Rig. As time has progressed, a lot of those people have kind of unfortunately gone their own way. For whatever reason, a lot of the people that were following him weren&#8217;t really like, they might have been into learning how to develop themes. They certainly were into WordPress. But working on a project like this is more than just knowing how to develop themes. You also have to know how the underlying tools work too.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So that&#8217;s been my biggest challenge is learning, what is Lightning CSS? How do you use it? What is esbuild? How does that work? When I first took it over, it was ran on Gulp. What is Gulp? And what is that, and how do I modify it? And like that&#8217;s kind of far beyond WordPress, and so I think people became aware of that over time. And so while I rose up to the challenge, other people were just kind of moved on to other things.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So it is largely me. We do have a handful of contributors that kind of, when they have time, you know, they&#8217;ll feel ambitious again and jump in and do some more contributions and they&#8217;ll fall back and do their own thing for a while. And so there&#8217;s a lot of that. It&#8217;s not a very active community, certainly not as active as it was when I first adopted it. However, we do have a Discord now. You can find a link to the Discord on the website. If you go to the Learn V3 link in the header, there&#8217;s links to our YouTube channel and the Discord server.</p>\n\n\n\n<p class=\"wp-block-paragraph\">So we are looking, I do want more of a community around WP Rig. And so I do encourage people to come on. Obviously we&#8217;ve been on GitHub this entire time, so if anybody wants to raise issues or submit a PR, there are guides on there. There&#8217;s a contributing.md file in there for anybody that wants to contribute, or wants to raise an issue. If you have ideas for how WP Rig could be better, that&#8217;s always been there. It&#8217;s just that, for one reason or another, it&#8217;s just not popular, which is a big reason why I&#8217;m on your show today actually is just to raise awareness about WP Rig now that I have had the opportunity to overhaul it dramatically over the past couple years.</p>\n\n\n\n<p class=\"wp-block-paragraph\">In my opinion, it was a little bit, it started to feel a little bit slow compared to most modern tools. If anybody&#8217;s familiar with like Vite, or just modern frontend development frameworks. In general, they use more modern tools that build things faster and better, and they&#8217;re leaner. And so WP Rig was falling behind a little bit in that regard. And so I did have to like overhaul the project a lot. That&#8217;s why we came out with the version three because it is a pretty substantial overhaul.</p>\n\n\n\n<p class=\"wp-block-paragraph\">And so now that we have version three and it is much better and there are all kinds of new features built into it as a result of it being faster, it&#8217;s now more capable. I want to raise awareness. A, I&#8217;ve already done the work, so it would be a shame for all that work to go unnoticed and unappreciated. But also, for anybody who was familiar with WP Rig from previous years, back in the version one, version two days, I think it&#8217;s important to make people aware that version three is substantially more capable than what it was prior.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:46:38] <strong>Nathan Wrigley:</strong> That&#8217;s wonderful. I&#8217;m just going to round off the episode by mentioning the URL once more so that after that clarion call, if people have been inspired and they have listened to this and think, I&#8217;d like to explore that. You know, for the multitude of reasons that we&#8217;ve covered in this topic. The URL, it&#8217;s really easy. It&#8217;s WP Rig, wprig.io. Go there, there&#8217;s a whole bunch of ways to get involved. So there&#8217;s the Learn documentation, there&#8217;s the contribute tab and so on and so forth. You can peruse at your leisure.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Rob, just before we end, is there a way that people could communicate with you more directly if they wanted to off the back of this? Is there a, like a, I don&#8217;t know, a social network or something that you frequent? Or a contact form that you&#8217;d like people to be mindful of?</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:47:22] <strong>Rob Ruiz:</strong> Yeah, sure. I mean, I am very responsive to people on LinkedIn, so if you want to find me on LinkedIn, I am on there, Rob Ruiz, just look me up. If it looks like it&#8217;s a Rob Ruiz that does WordPress stuff, it&#8217;s probably me. And then of course, I&#8217;m on the Discord server. So if you want to communicate directly with me, joining the Discord and then messaging me directly is a nice way to do that. I&#8217;d love to help people, hold their hand if needed, get up and running with WP Rig. If you have any questions about specifics, I&#8217;m happy to address them, or you just need a little guidance, I&#8217;d be happy to help there as well.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:47:54] <strong>Nathan Wrigley:</strong> Well, thank you so much for chatting to me today, Rob. It&#8217;s been really interesting. So once more, just before we end to find out more. Rob Ruiz, thank you very much for chatting to me today.</p>\n\n\n\n<p class=\"wp-block-paragraph\">[00:48:04] <strong>Rob Ruiz:</strong> Thank you so much for your time, Nathan. I really appreciate it.</p>\n</div></details>\n\n\n\n<p class=\"wp-block-paragraph\">On the podcast today we have <a href=\"https://www.linkedin.com/in/robcruiz/\">Rob Ruiz</a>.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Rob has been involved in the WordPress ecosystem since around 2010. He began as a designer, but over the years WordPress has helped him transition into a developer, software engineer, and now an architect. Currently, he’s working full-time at an agency while still taking on projects independently.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The main topic for today’s conversation centres around themes, a subject that hasn’t been covered in depth on the podcast for quite some time. You see, Rob is the current custodian of WP Rig, a free and open source toolkit for WordPress theme development. WP Rig offers a modern, minimal, and best-practice driven starting point for developers who want to build custom themes, providing tools like Composer and Node integration to streamline workflows, enforce coding standards, and enable the use of future-facing CSS features right now.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We start the episode with Rob sharing what attracted him to WP Rig, and his journey from user to project maintainer. We talk about who WP Rig is for, from experienced developers to those just starting to dip their toes into theme building and code customisation.</p>\n\n\n\n<p class=\"wp-block-paragraph\">The discussion moves on to talking about what a theme development framework actually is, and why this approach might suit people wanting more control, and education, in their WordPress journey. Rob describes the learning curve, the workflow, and the satisfaction of creating your own theme from scratch, while highlighting tools and guardrails built into WP Rig that make professional standards and best practices accessible to all.</p>\n\n\n\n<p class=\"wp-block-paragraph\">We also get into how WP Rig fits into the changing WordPress ecosystem. With the advent of full site editing and block-based themes, Rob explains how WP Rig has evolved to stay relevant, supporting classic, hybrid, and block-based paradigms, even enabling block development at the theme level.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Towards the end, we discuss the community behind WP Rig, how you can get involved, and the many educational resources available for those who want to learn theme development, or even become contributors themselves.</p>\n\n\n\n<p class=\"wp-block-paragraph\">If you’re interested in building custom WordPress themes, want to understand the nuts and bolts of theme frameworks, or are simply looking for a modern and educational starting point for WordPress tinkering, this episode is for you.</p>\n\n\n\n<h2 class=\"wp-block-heading\">Useful links</h2>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wprig.io\">WP Rig website</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.linkedin.com/in/robcruiz/\">Rob on LinkedIn</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wordpress.org/themes/\">WordPress.org theme repository</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://postcss.org\">PostCSS</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.wordpress.org/block-editor/getting-started/devenv/get-started-with-wp-env/\">Get started with wp-env</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://developer.wordpress.com/studio/\">WordPress Studio</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://codex.wordpress.org/WordPress_Coding_Standards\">WordPress Coding Standards</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://wptavern.com/podcast/15-morten-rand-hendriksen-on-governing-open-source-projects\">Morten Rand-Hendriksen on the WP Tavern Jukebox podcast</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://discord.com/invite/su2et45Rat\">WP Rig&#8217;s Discord</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://www.youtube.com/@wprig1203\">WP Rig&#8217;s YouTube channel</a></p>\n\n\n\n<p class=\"wp-block-paragraph\"><a href=\"https://vite.dev/guide/\">Vite</a></p>\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 04 Mar 2026 17:08:13 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:14:\"Nathan Wrigley\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:11;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:92:\"Open Channels FM: Inside the Checkout Summit: What WooCommerce Events Mean for the Ecosystem\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=1650498\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:98:\"https://openchannels.fm/inside-the-checkout-summit-what-woocommerce-events-mean-for-the-ecosystem/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:191:\"In this episode, James Kemp, Katie Keith, and Rodolfo Melogli discuss the revival of in-person WooCommerce events like Checkout Summit, the influence of AI on businesses, and community value.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 04 Mar 2026 11:32:07 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:12;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:70:\"Open Channels FM: AI’s Impact on Human Interaction with the Open Web\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:33:\"https://openchannels.fm/?p=539201\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:74:\"https://openchannels.fm/ais-impact-on-human-interaction-with-the-open-web/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:227:\"AI\'s rapid evolution is reshaping web interactions, with automated traffic outpacing human engagement. This shift raises concerns about content value, as creators struggle to balance utility and genuine human experience online.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 04 Mar 2026 09:47:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:13;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\";s:88:\"Open Channels FM: Open Channels FM, a Media Partner for CloudFest 2026 and the Hackathon\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"guid\";a:1:{i:0;a:5:{s:4:\"data\";s:34:\"https://openchannels.fm/?p=1650323\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:4:\"link\";a:1:{i:0;a:5:{s:4:\"data\";s:97:\"https://openchannels.fm/open-channels-fm-is-a-media-partner-for-cloudfest-2026-and-the-hackathon/\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:11:\"description\";a:1:{i:0;a:5:{s:4:\"data\";s:112:\"For the third year in the row we are proud to be a media sponsor for both the CloudFest Hackathon and CloudFest.\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}s:7:\"pubDate\";a:1:{i:0;a:5:{s:4:\"data\";s:31:\"Wed, 04 Mar 2026 09:33:00 +0000\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}s:32:\"http://purl.org/dc/elements/1.1/\";a:1:{s:7:\"creator\";a:1:{i:0;a:5:{s:4:\"data\";s:8:\"Bob Dunn\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";}}}}}i:14;a:6:{s:4:\"data\";s:21:\"\n	\n	\n	\n	\n	\n	\n	\n	\n	\n	\n\";s:7:\"attribs\";a:0:{}s:8:\"xml_base\";s:0:\"\";s:17:\"xml_base_explicit\";b:0;s:8:\"xml_lang\";s:0:\"\";s:5:\"child\";a:2:{s:0:\"\";a:5:{s:5:\"title\";a:1:{i:0;a:5:{s:4:\"data\