INSERT INTO `wp_postmeta` VALUES (501,835,'_elementor_data','[{\"id\":\"55d6b19\",\"elType\":\"container\",\"settings\":{\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"80\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"60\",\"left\":\"0\",\"isLinked\":false},\"margin_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"40\",\"left\":\"0\",\"isLinked\":false},\"flex_gap\":{\"size\":30,\"column\":\"30\",\"row\":\"30\",\"unit\":\"px\",\"isLinked\":true},\"container_sticky_offset\":50,\"scroll_y\":-80},\"elements\":[{\"id\":\"5eef987c\",\"elType\":\"widget\",\"settings\":{\"subtitle\":\"\",\"title\":\"MacBook Pro M1 Pro\",\"after_title\":\"<p>Phenomenal performance for professionals<\\/p>\",\"title_typography_typography\":\"custom\",\"title_typography_font_size\":{\"unit\":\"px\",\"size\":24,\"sizes\":[]},\"title_typography_font_size_tablet\":{\"unit\":\"px\",\"size\":22,\"sizes\":[]},\"text_typography_typography\":\"custom\",\"text_typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_title\"},{\"id\":\"68b44cb9\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost:10003\\/wp-content\\/uploads\\/2022\\/12\\/macbook-pro.jpg\",\"id\":\"8867\",\"alt\":\"\",\"source\":\"library\"},\"alignment\":\"center\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_image_or_svg\"},{\"id\":\"5afb6d63\",\"elType\":\"widget\",\"settings\":{\"text\":\"<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Ut elit tellus, luctus nec ullamcorper mattis, pulvinar dapibus leo.<\\/p>\",\"text_alignment\":\"center\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_text_block\"}],\"isInner\":false},{\"id\":\"3e989803\",\"elType\":\"container\",\"settings\":{\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"80\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"60\",\"left\":\"0\",\"isLinked\":false},\"margin_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"40\",\"left\":\"0\",\"isLinked\":false},\"flex_gap\":{\"size\":null,\"column\":\"\",\"row\":\"\",\"unit\":\"px\",\"isLinked\":true},\"container_sticky_offset\":50,\"scroll_y\":-80},\"elements\":[{\"id\":\"3d704cac\",\"elType\":\"widget\",\"settings\":{\"subtitle\":\"\",\"title\":\"M1 Pro chip\",\"after_title\":\"\",\"size\":\"small\",\"align\":\"left\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_title\"},{\"id\":\"13be8378\",\"elType\":\"widget\",\"settings\":{\"text\":\"<p>The new M1 Pro processor allows professionals to create what previously seemed impossible. It has more cores and more combined memory (up to 10 cores in the CPU and up to 16 in the graphics). Neural Engine system, dedicated media processors for encoding and decoding files with support for H.264, HEVC and ProRes codecs. This chip is designed for ambitious people and large-scale tasks that other specialists simply won\'t take on.<\\/p>\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_text_block\"},{\"id\":\"3ea7f3b0\",\"elType\":\"container\",\"settings\":{\"structure\":\"20\",\"flex_direction\":\"row\",\"flex_gap\":{\"size\":null,\"column\":\"\",\"row\":\"\",\"unit\":\"px\",\"isLinked\":true},\"content_width\":\"full\",\"flex_direction_mobile\":\"column\",\"container_sticky_offset\":50,\"scroll_y\":-80},\"elements\":[{\"id\":\"166d7509\",\"elType\":\"widget\",\"settings\":{\"icon_type\":\"icon\",\"icon_text\":\"53\",\"image\":{\"url\":\"http:\\/\\/localhost:10003\\/wp-content\\/uploads\\/2022\\/12\\/m1-pro.jpg\",\"id\":\"8868\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"full\",\"subtitle\":\"\",\"title\":\"Scary fast\",\"content\":\"<p>Up to 10-core CPU Up to 16-core GPU Up to 32GB of unified memory Up to 200GB\\/s memory bandwidth<\\/p>\",\"btn_text\":\"\",\"link\":{\"url\":\"\",\"is_external\":false,\"nofollow\":false,\"custom_attributes\":\"\"},\"_padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"scroll_y\":-80,\"_background_background\":\"classic\",\"_background_color\":\"#10101008\",\"_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"%\",\"size\":50,\"sizes\":[]},\"_element_custom_width_mobile\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"wd_infobox\"},{\"id\":\"5d65e36a\",\"elType\":\"widget\",\"settings\":{\"icon_type\":\"icon\",\"icon_text\":\"53\",\"image\":{\"url\":\"http:\\/\\/localhost:10003\\/wp-content\\/uploads\\/2022\\/12\\/m1-max.jpg\",\"id\":\"8869\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"full\",\"subtitle\":\"\",\"title\":\"Scary fast\",\"content\":\"<p>10-core CPU Up to 32-core GPU Up to 64GB of unified memory Up to 400GB\\/s memory bandwidth<\\/p>\",\"btn_text\":\"\",\"link\":{\"url\":\"\",\"is_external\":false,\"nofollow\":false,\"custom_attributes\":\"\"},\"_padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"scroll_y\":-80,\"_background_background\":\"classic\",\"_background_color\":\"#10101008\",\"_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"%\",\"size\":50,\"sizes\":[]},\"_element_custom_width_mobile\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"wd_infobox\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"150bd0e9\",\"elType\":\"container\",\"settings\":{\"flex_gap\":{\"size\":null,\"column\":\"\",\"row\":\"\",\"unit\":\"px\",\"isLinked\":true},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"30\",\"left\":\"0\",\"isLinked\":fals