INSERT INTO `wp_postmeta` VALUES (552,920,'_elementor_data','[{\"id\":\"570d538e\",\"elType\":\"container\",\"settings\":{\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"80\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"60\",\"left\":\"0\",\"isLinked\":false},\"margin_mobile\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"40\",\"left\":\"0\",\"isLinked\":false},\"flex_gap\":{\"size\":30,\"column\":\"30\",\"row\":\"30\",\"unit\":\"px\",\"isLinked\":true},\"container_sticky_offset\":50,\"scroll_y\":-80},\"elements\":[{\"id\":\"7195dfdc\",\"elType\":\"widget\",\"settings\":{\"subtitle\":\"\",\"title\":\"MacBook Pro M1 Pro\",\"after_title\":\"<p>Phenomenal performance for professionals<\\/p>\",\"title_typography_typography\":\"custom\",\"title_typography_font_size\":{\"unit\":\"px\",\"size\":24,\"sizes\":[]},\"title_typography_font_size_tablet\":{\"unit\":\"px\",\"size\":22,\"sizes\":[]},\"text_typography_typography\":\"custom\",\"text_typography_font_size\":{\"unit\":\"px\",\"size\":16,\"sizes\":[]},\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_title\"},{\"id\":\"628d361a\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost:10003\\/wp-content\\/uploads\\/2022\\/12\\/macbook-pro.jpg\",\"id\":\"8867\",\"alt\":\"\",\"source\":\"library\"},\"alignment\":\"center\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_image_or_svg\"},{\"id\":\"3701d698\",\"elType\":\"widget\",\"settings\":{\"text\":\"<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Ut elit tellus, luctus nec ullamcorper mattis, pulvinar dapibus leo.<\\/p>\",\"text_alignment\":\"center\",\"scroll_y\":-80},\"elements\":[],\"widgetType\":\"wd_text_block\"}],\"isInner\":false},{\"id\":\"5a9f871c\",\"elType\":\"container\",\"settings\":{\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"80\",\"left\":\"0\",\"isLinked\":false},\"margin_tablet\":