:false,\"nofollow\":false,\"custom_attributes\":\"\"},\"_padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"scroll_y\":-80,\"_background_background\":\"classic\",\"_background_color\":\"#10101008\",\"_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"%\",\"size\":50,\"sizes\":[]},\"_element_custom_width_mobile\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"wd_infobox\"},{\"id\":\"47d2c542\",\"elType\":\"widget\",\"settings\":{\"icon_type\":\"icon\",\"icon_text\":\"53\",\"image\":{\"url\":\"http:\\/\\/localhost:10003\\/wp-content\\/uploads\\/2022\\/12\\/m1-max.jpg\",\"id\":\"8869\",\"alt\":\"\",\"source\":\"library\"},\"image_size\":\"full\",\"subtitle\":\"\",\"title\":\"Scary fast\",\"content\":\"<p>10-core CPU Up to 32-core GPU Up to 64GB of unified memory Up to 400GB\\/s memory bandwidth<\\/p>\",\"btn_text\":\"\",\"link\":{\"url\":\"\",\"is_external\":false,\"nofollow\":false,\"custom_attributes\":\"\"},\"_padding\":{\"unit\":\"px\",\"top\":\"20\",\"right\":\"20\",\"bottom\":\"20\",\"left\":\"20\",\"isLinked\":true},\"scroll_y\":-80,\"_background_background\":\"classic\",\"_background_color\":\"#10101008\",\"_border_radius\":{\"unit\":\"px\",\"top\":\"10\",\"right\":\"10\",\"bottom\":\"10\",\"left\":\"10\",\"isLinked\":true},\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"%\",\"size\":50,\"sizes\":[]},\"_element_custom_width_mobile\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"wd_infobox\"}],\"isInner\":true}],\"isInner\":false},{\"id\":\"604fee5f\",\"elType\":\"container\",\"settings\":{\"flex_gap\":{\"size\":null,\"column\":\"\",\"row\":\"\",\"unit\":\"px\",\"isLinked\":true},\"margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"30\",\"left\":\"0\",\"isLinked\":fal