center\",\"container_sticky_offset\":50},\"elements\":[{\"id\":\"66d20f66\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost:10003\\/wp-content\\/uploads\\/2022\\/12\\/mac-os-1.jpg\",\"id\":\"8871\",\"alt\":\"\",\"source\":\"library\"},\"alignment\":\"center\",\"scroll_y\":-80,\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"%\",\"size\":58,\"sizes\":[]},\"_element_custom_width_mobile\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"wd_image_or_svg\"},{\"id\":\"75504fd\",\"elType\":\"widget\",\"settings\":{\"image\":{\"url\":\"http:\\/\\/localhost:10003\\/wp-content\\/uploads\\/2022\\/12\\/mac-os-2.jpg\",\"id\":\"8872\",\"alt\":\"\",\"source\":\"library\"},\"alignment\":\"center\",\"scroll_y\":-80,\"_element_width\":\"initial\",\"_element_custom_width\":{\"unit\":\"%\",\"size\":42,\"sizes\":[]},\"_element_custom_width_mobile\":{\"unit\":\"%\",\"size\":100,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"wd_image_or_svg\"}],\"isInner\":true}],\"isInner\":false}]');
