INSERT INTO `wp_posts` VALUES (1592,1,'2022-12-09 15:49:51','2022-12-09 15:49:51','<link rel=\"stylesheet\" id=\"wd-banner-css\" href=\"https://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/themes/woodmart/css/parts/el-banner.min.css?ver=7.3.0\" type=\"text/css\" media=\"all\" /> 						<link rel=\"stylesheet\" id=\"wd-banner-hover-zoom-css\" href=\"https://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/themes/woodmart/css/parts/el-banner-hover-zoom.min.css?ver=7.3.0\" type=\"text/css\" media=\"all\" /> 					\n																					<img width=\"920\" height=\"560\" src=\"http://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/uploads/sites/8/2023/01/available-new-7000-series.jpg\" alt=\"\" decoding=\"async\" loading=\"lazy\" srcset=\"https://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/uploads/sites/8/2023/01/available-new-7000-series.jpg 920w, https://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/uploads/sites/8/2023/01/available-new-7000-series-400x243.jpg 400w, https://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/uploads/sites/8/2023/01/available-new-7000-series-768x467.jpg 768w, https://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/uploads/sites/8/2023/01/available-new-7000-series-600x365.jpg 600w, https://dummy.xtemos.com/woodmart2/mega-electronics-elementor/wp-content/uploads/sites/8/2023/01/available-new-7000-series-150x91.jpg 150w\" sizes=\"(max-width: 920px) 100vw, 920px\" />																		\n								FAST AND POWERFUL PROCESSOR							\n													<h4 data-elementor-setting-key=\"title\">\n								Available new 7000 Series							</h4>\n			<a >\n					Buy Now				\n							</a>\n																					<img width=\"920\" height=\"560\" src=\"http://localhost:10003/wp-content/uploads/2022/12/real-speed-with5ghz-home-router.jpg\" alt=\"\" decoding=\"async\" loading=\"lazy\" srcset=\"http://localhost:10003/wp-content/uploads/2022/12/real